quests[5521] = { id = 5521, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> {name} - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.", sourceObjective = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Lightspark at Chillwind Camp, Western Plaguelands.", progress = "Salutations, mighty {class}!  Have you brought the valor tokens I asked of you?  Once you hand them to me, I will issue you your own Chromatic Mantle of the Dawn.", completion = "Most impressive, {name} - the Chromatic Mantle of the Dawn is now yours!\n\nAs long as you maintain Exalted status with the Argent Dawn, you will be able to purchase additional Chromatic Mantles.  They will be made available to you immediately from any of the Dawn's quartermasters.", sourceObjectiveStatus = "unverified-source-field" }
quests[5522] = { id = 5522, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leonid Barthalomew", description = "I received a message from my master, Vectus.  Well, the message wasn't really from Vectus...it was from someone named Leonid Barthalomew.  I don't know Leonid, but he knew my master, and no one knows my master unless he allows it.\n\nLeonid says Vectus wants the dragon eggs.  He wants you to deliver them to him at the Light's Hope Chapel in the Eastern Plaguelands.\n\nThat hurts!  Why you?  Doesn't Vectus trust me?  Oh, never mind... just take the eggs and tell Leonid that I did what our master commanded.", sourceObjective = "Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands.", progress = "You are the one up to mischief in Blackrock Spire, yes?  Do you have what I asked for?", completion = "Ah, very good.  You do not know the evil power for whom you have labored, but now you will know the truth.  And fear not--I am no servant of that master.  I am Leonid Barthalomew, known as \"the Revered\" to my brethren in the Argent Dawn.\n\nI tricked Tinkee into sending you and the dragon eggs to me.  And it is good that my trick was successful, for had these eggs reached their intended destination, a great power would have fallen into the hands of the enemy.", sourceObjectiveStatus = "unverified-source-field" }
quests[5524] = { id = 5524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chromatic Mantle of the Dawn", description = "<Brother/Sister> {name} - your deeds on behalf of the Argent Dawn are far too numerous to be recounted easily.  As a fitting tribute, I'll part with one of our special Chromatic Mantles of the Dawn - a version that protects the wearer from all forms of resistible magic simultaneously.  Chromatic Mantles of the Dawn are reserved for only the mightiest of the Dawn's heroes!\n\nBring to me twenty-five valor tokens as a sign of tribute, and I'll give you the finest of all our mantles.", sourceObjective = "Bring 25 Argent Dawn Valor Tokens to Quartermaster Hasana at the Bulwark, Western Plaguelands.", progress = "Salutations, mighty {class}!  Have you brought the valor tokens I asked of you?  Once you hand them to me, I will issue you your own Chromatic Mantle of the Dawn.", completion = "Most impressive, {name} - the Chromatic Mantle of the Dawn is now yours!\n\nAs long as you maintain Exalted status with the Argent Dawn, you will be able to purchase additional Chromatic Mantles.  They will be made available to you immediately from any of the Dawn's quartermasters.", sourceObjectiveStatus = "unverified-source-field" }
quests[5525] = { id = 5525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Knot!", progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", completion = "You - ranked number one.  Everyone else - ranked number two or lower.  Oh, thank you for freeing me!\n\nI knew my life was destined for more than just being an appetizer to some ogre!" }
quests[5526] = { id = 5526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shards of the Felvine", description = "Your knowledge of Eldre'Thalas - Dire Maul - in Feralas will now come into play, {name}.  In the eastern part of the ruined city is where Alzzin the Wildshaper has exerted his corrupt dominion.  Go there with all due haste and brave whatever challenges await you.\n\nThe Fruit of Fertility, now corrupted as the Felvine, should be close to Alzzin.  When he falls, capture whatever essence of the Felvine you can.  Seal it in the Reliquary, and bring it to me.\n\nGood luck, and Cenarion's speed.", sourceObjective = "Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade.", progress = "With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch.  Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.\n\nI know Milli would have had it no other way...", completion = "It is done, brave {class}, and with that the Cenarion Circle is in your debt.  Though the war is far from over, a great battle has been won against those who would bring about our doom.\n\nPlease - accept this as a token of our enduring gratitude.  Know that you are welcomed here as a hero of the Cenarion Circle for your great deed, {name}.  Thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[5527] = { id = 5527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Reliquary of Purity", description = "The first step is to find a container capable of holding an extremely corruptible substance without the handler suffering ill effects.  There is only one sort device I am aware of that could possibly contain something as vile as the Felvine: a Reliquary of Purity.\n\nDeep in the wasteland of Silithus is the remnants of the night elf village known as Southwind.  I know one was there many, many years ago.  If we are to succeed, I need you to scour those ruins in the hopes of reclaiming it.", sourceObjective = "Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade.", progress = "A Reliquary of Purity is an artifact unto itself.  Few were ever made, and almost all of them were thought to have been lost over time.\n\nI admit I have known about the one in Southwind for a little while now.  Honestly, with the rising turmoil in Silithus, I thought to keep our secrets just that - a secret.  To poke and prod would only cause suspicions of our enemies to rise.\n\nAlas, the time for complacency is at an end, especially with the situation in Eldre'Thalas.", completion = "Indeed, you are as resourceful as many claim.  The Cenarion Circle is blessed to have you working in our stead.\n\nWith the Reliquary once more in our hands, my mind is at ease.  I feel more comfortable asking you to not only face down a malfeasant demon, but also to bring back a dangerous item in the process...", sourceObjectiveStatus = "unverified-source-field" }
quests[5528] = { id = 5528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gordok Taste Test", sourceObjective = "You da big boss now, so you get free sample of my better brews!  These drinks boost you up AND give you good buzz!  These are da good ones, chief... you try and tell Kreeg yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5529] = { id = 5529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plagued Hatchlings", description = "The Argent Dawn recently learned that the Scourge are creating their own plagued dragonflight!  We must stop them -- if the Scourge gain a force of dragons they'll sweep across Azeroth unchecked!\n\nTheir necromancers are breeding plagued dragons at the Scholomance, in the middle of Darrowmere Lake.\n\nGo to the Scholomance and kill as many hatchlings as you can... before they get any bigger!", sourceObjective = "Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel.", completion = "Well done, {name}!  It'll be a long time before they can grow another clutch of dragons.\n\n...At least, I hope it will!", sourceObjectiveStatus = "unverified-source-field" }
quests[5531] = { id = 5531, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Betina Bigglezink", description = "The eggs you brought were to be used in Scourge experiments to create a plagued dragonflight.  These frozen black dragon eggs would have been invaluable in their studies, and would have assuredly quickened their timetable.\n\nNow, it is time we ended their research.\n\nTake the frozen eggs to Betina Bigglezink outside.  She is well-learned in science and alchemy, and has produced a weapon we can use against the Scourge.  With your help, we will deal them a heavy blow.", sourceObjective = "Bring the Frozen Eggs to Betina Bigglezink.", progress = "Hello, {name}!  I heard you were here with some dragon eggs?  Well, let's see them!", completion = "There they are!  And in such a nice container.  The perfect size!\n\nWe'll keep these eggs in a safe place so we can study them later, but right now we need that thing you brought them in.\n\nI have created a device with a very specific use: to destroy the undead scholars of the Scholomance.  They are studying dragons in their efforts to create a plagued dragonflight, and we must halt their progress.\n\nI call the device Dawn's Gambit, because... I'm not sure if it works!\n\nWill you find out for us?", sourceObjectiveStatus = "unverified-source-field" }
quests[5533] = { id = 5533, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomance", description = "On the island of Caer Darrow lies Scholomance - a wretched center of Scourge necromancy and evil.  Our enemy dwells within, conducting unspeakable acts of depravity on unwitting victims... at least, we surmise as much.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nAlchemist Arbington is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your worth to me, and now I entrust this task to you.  Speak with him on this matter.", sourceObjective = "Speak with Alchemist Arbington at Chillwind Point, Western Plaguelands.", completion = "Well met, {class}.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire a key... one that will let you past the front door.\n\nI can only imagine what horrid sights are to be seen inside, {name}.  I don't know how you heroic types do it sometimes...", sourceObjectiveStatus = "unverified-source-field" }
quests[5534] = { id = 5534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kim'jael's \"Missing\" Equipment", description = "What?! What?!\n\nThat wasn't good enough for you? You know how expensive those explosives are? They sell for... oh, nevermind. Fine, you want to make some real money? Cause that's how business is done: you prove you're a valuable employee and then you're rewarded adequately after you stick it out some.\n\nIf you're a \"valuable\" employee, then hit the Ruins of Eldarath and find me some rune that them Blood elves were lookin' for. The naga apparently have it in their possession.", sourceObjective = "Find Some Rune that the naga have in their possession in the Ruins of Eldarath and return it to Kim'jael in Azshara.", progress = "Well, {name}? Where is the rune? You are a good employee, right? You're here to help?\n\nDon't make me think twice about paying you what we agreed upon. What? Oh, we didn't agree on anything? Oh, great... then take your time--just know that it'll be a lot less if you take a long time.", completion = "Haha! Wonderful!\n\nI'll be sure to find out what this is for and why Magus Rimtori--she's the cow that hired me--wanted it. Hah! I got you now, stinkin' Blood elves! Kim'jael! Ha! I'll teach them who the rats are!\n\nYa did good, {name}. Thanks a bundle. Here, take this coin and be off with ya--I've got some things to figure out.", sourceObjectiveStatus = "unverified-source-field" }
quests[5535] = { id = 5535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Unrest", description = "Long ago, the Highborne were some of the most powerful students of the arcane the night elves ever produced. The corruption that comes along with such studies caused much harm to night elf society and greatly affected all of Azeroth... as I'm sure you well know.\n\nI promised the Sentinels that I would release the spirits from their mortal bonds as I find them. If you would do the same, then I am sure I can reward you some.\n\nThe spirits haunt the Shadowsong Shrine to the northeast of here.", sourceObjective = "Destroy 6 Highborne Apparitions and 6 Highborne Lichlings before returning to Loh'atu in Azshara.", progress = "How goes your search for the Highborne spirits, {class}?\n\nMany events have caused all the races of Azeroth great suffering, but for some reason, these spirits seem to be a plague for all people. Perhaps it is there continued desire for any arcane magic--such desire is a harbinger of the Burning Legion, and we know what that can lead to.", completion = "Well done, {class}. Thank you for your help. The spirits are at peace, and the threats that their desire for the arcane draw have been lessened.\n\nI am sure that both sides of the conflict that ravishes Azeroth will see you are above such things.", sourceObjectiveStatus = "unverified-source-field" }
quests[5536] = { id = 5536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Land Filled with Hatred", description = "The satyr, a disfigured, evil aspect of the night elves, now infect the sacred lands once traveled by Cenarius. I cannot speak for the night elves when it comes to all the atrocities those demonic creatures have committed, but I have sworn an oath to the Earthmother to aid the elves in ridding the land of such a nuisance.\n\nI am sure you would prove yourself if you aided me in purging them.\n\nNortheast of here, you can find the Haldarr clan. Return to me after you've tested yourself against their power.", sourceObjective = "Kill 6 Haldarr Satyr, 2 Haldarr Tricksters, 2 Haldarr Felsworn and then return to Loh'atu on the border of Ashenvale.", progress = "How goes your battle against the satyr, {class}?\n\nAre they as strong as you thought? Stronger? Or perhaps they were nothing to your own might.", completion = "Well done, {class}. I see you're not only skilled but cunning. To defeat such creatures is a testament to your loyalty to the tenants of the Earthmother, even if you do not recognize her as your own deity. She is in all things on this planet and beyond. Her eyes, one dark and one light, travel across the skies always gazing down upon us.\n\nPlease, take this small amount of coin in appreciation for what you have done.", sourceObjectiveStatus = "unverified-source-field" }
quests[5537] = { id = 5537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skeletal Fragments", description = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, {name}.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.", sourceObjective = "Bring 15 Skeletal Fragments to Alchemist Arbington at Chillwind Point, Western Plaguelands.", progress = "As morbid as it sounds, we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, {name}!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder.", sourceObjectiveStatus = "unverified-source-field" }
quests[5538] = { id = 5538, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mold Rhymes With...", description = "The goblin you will need to speak with is Krinkle Goodsteel.  He peddles his skills to the highest bidder in Gadgetzan, within the Tanaris desert.  He'll likely be the only one who can produce the mold we need, and his services won't come cheap.  We now ask for you to dig deep by footing whatever fee he will charge.\n\nI'm an alchemist, not a banker.  If I had gold lying around, I certainly wouldn't be here.\n\nI guess I said the quiet part out loud again.  Oops.\n\nGadgetzan awaits you!  Good luck!", sourceObjective = "Bring the Imbued Skeletal Fragments and 15 gold coins to Krinkle Goodsteel in Gadgetzan.", progress = "Yeah, I know who you are, and I know why you're here.  Arbington sent word to me before you arrived.  Let's cut to the deal at hand, now shall we?\n\nI've got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation.  I'll pack the skeletal fragments into the mold for you, and I'll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.\n\nWho says mercenaries don't offer competitive deals!", completion = "Arbington said you'd deliver the goods, and deliver you have!  A deal is a deal; let me pack the fragments into the mold for you.\n\nDid Arbington imbue them already?  Excellent... otherwise, it would have been a long trip back to Chillwind Point for you.", sourceObjectiveStatus = "unverified-source-field" }
quests[5541] = { id = 5541, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ammo for Rumbleshot", description = "Hegnar Rumbleshot sells guns off the road to Anvilmar.  Riflemen and mortar teams spend a lot of time practicing out near his shop, and he's always needing fresh ammunition.\n\nBut... the last crate of ammo I sent him got lost along the way.  My courier said he was camped near the Grizzled Den when wendigo chased him away... and the fool left Rumbleshot's ammo behind!\n\n{name}, can you get that ammo and take it to Rumbleshot?  He's been waiting on it and I'm sure he's running low.", sourceObjective = "Bring Rumbleshot's Ammo to Hegnar Rumbleshot in Dun Morogh.", progress = "I hope you're not here for ammo, because I'm almost out!", completion = "Great, more ammo!  Old Loslor's shipment finally came through!  The ammo might be late, but just like my grand daddy used to tell me: late's better than never!\n\nThank you much, {name}.  I already have buyers eager for this stuff!", sourceObjectiveStatus = "unverified-source-field" }
quests[5542] = { id = 5542, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demon Dogs", description = "If you are going to remain here, I ask only that you earn your keep. We have many nuisances that could use some 'discipline.'\n\nYou can start with the Plaguehounds and their runts.\n\nI cannot offer much in return, but you are guaranteed a warm meal and some conversation should you succeed.", sourceObjective = "Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete.", progress = "Do not pity the demon dogs, {race}. They are abominations!", completion = "Well done, {name}. Come. Rest. Let us eat and talk of days long past!", sourceObjectiveStatus = "unverified-source-field" }
quests[5543] = { id = 5543, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Tinged Skies", description = "Woe to those that foolishly wander into the Plaguelands. All manner of foulness inhabit these woods - from the fanatical Scarlet Crusade, who will kill any that do not bear the mark of the Crusade, to the murderous Scourge, who only look to bolster their numbers by adding more undead to their ranks.\n\nEven the wildlife have been transformed into rapacious, man eating beasts. I ask that you destroy those that would strike from the skies: The Plaguebats.", sourceObjective = "Slay 30 Plaguebats and return to Tirion Fordring.", progress = "Do not underestimate the winged vermin, {race}. The Plague has given them supernatural abilities.", completion = "You are a shining example of decency, {race}! It has been long since I have felt the blood of heroes pump through my veins. Your acts of bravery are uplifting!", sourceObjectiveStatus = "unverified-source-field" }
quests[5544] = { id = 5544, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carrion Grubbage", description = "My food supplies are running low, {race}. I am ashamed to admit that I might not have enough food to share with you.\n\nCould you assist an old man with a simple task? Around here, the only manner of beast unaffected by the ravages of the Plague are the Carrion worms. While rather bland in taste, the meat of the worms can easily be preserved to last for months. I will need several hundred pounds to restock for the coming winter!", sourceObjective = "Seek out the Carrion Grubs and Devourers of the region. Slay them and harvest their meat. Return to Tirion Fordring when you have gathered 15 Slabs of Carrion Worm Meat.", progress = "You will grow to tolerate the taste, {race}.", completion = "May the Light watch over you! Bless you, young one.", sourceObjectiveStatus = "unverified-source-field" }
quests[5545] = { id = 5545, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Trouble", description = "I've got a real problem on my hands. I have a deadline looming for an order of lumber, and I'm running out of time. The wolves and bears north of here have chased my workers away from the bundles of wood that they've already chopped.\n\nI've already talked to Deputy Rainer about clearing the animals, but I need someone to go collect the wood for me. If you could collect eight bundles of wood for me I might just make my deadline.", sourceObjective = "Bring 8 Bundles of Wood to Raelen at the Eastvale Logging Camp.", progress = "That deadline isn't getting any further away, {class}. Please hurry and collect those bundles of wood.", completion = "Excellent! Thanks to you, I should be able to complete the order in time. To show my gratitude, I would like to offer some coin as compensation for your troubles.\n\nThank you and farewell.", sourceObjectiveStatus = "unverified-source-field" }
quests[5561] = { id = 5561, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kodo Roundup", description = "Bibbly thinks he is the only goblin in Desolace who knows how to make money.  Well, the only caravan brave enough to travel these parts relies on me.  Ever since I learned how to rejuvenate and control aged kodos with my kodo kombobulator, the caravan owner Cork, Rigger, and I entered a partnership.\n\nTake the kombobulator and use it on any ancient or aged kodos; it will jolt the beast into a tamed kodo and force it to follow you.  Once you have a kodo tamed, bring it back to me.", sourceObjective = "Bring 3 Tamed Kodos and the Kodo Kombobulator back to Smeed Scrabblescrew at Scrabblescrew's Camp.", progress = "The caravan will be here shortly; do you have the five new tamed kodos I was asking for?", completion = "<Smeed Scrabblescrew begins counting.>\n\nThree, four, and five... excellent, I ask for five tamed kodos and I get five tamed kodos... I am going to be rich... yes, very rich! I hope to see the look on Bibbly's green face when he hears about my success!", sourceObjectiveStatus = "unverified-source-field" }
quests[5581] = { id = 5581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portals of the Legion", description = "Here it is - the Hand of Iruxos.\n\nGot it from one of the Burning Blade leaders myself.\n\nYou must possess it if the demon portals at Mannoroc Coven are to be banished... which is what I now ask you to do.\n\nWith the demon threat increasing we must close these portals to stem the tide of demons to this world.", sourceObjective = "Banish 6 Portals at Mannoroc Coven and return to Felgur Twocuts at Ghost Walker Post.", progress = "Have you banished the demon portals at Mannoroc Coven?", completion = "You are to be commended, {name}.  Your effort has helped greatly in fighting the demon threat, and all of Azeroth is safer because of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[5582] = { id = 5582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Healthy Dragon Scale", description = "This is a scale shed from a plagued dragon hatchling.  But unlike the other pocked, oozing scales on the infant beast, this rare scale is healthy and unmarred.\n\nBetina Bigglezink will want a sample of this to study.", sourceObjective = "Bring the Healthy Dragon Scale to Betina Bigglezink at the Light's Hope Chapel in Eastern Plaguelands.", progress = "{name}, do you have something to show me?", completion = "Excellent!  This will be invaluable in my continued studies of the machinations of the Scourge.  Thank you, {name}, and if you find more of these scales please bring them to me!", sourceObjectiveStatus = "unverified-source-field" }
quests[5601] = { id = 5601, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sister Pamela", description = "I fled Lordaeron during the great war, and was lucky to escape before the Scourge swept through my homeland and turned it into a plagued nightmare!  I was lucky, but my family was not.  I fear they were all killed during the battle of Darrowshire.\n\nDarrowshire is a village in the Eastern Kingdoms, nestled in the southern hills of what is now the Eastern Plaguelands.  Will you go there and search for my family?  I miss them so much, especially my little sister Pamela.\n\nPlease, find her for me!", sourceObjective = "Find Pamela Redpath in Darrowshire.", completion = "Where is my sister Jessica?  She left so long ago, when I was just a little girl.  She cried so much when she went away.  I don't know why she cried!  Maybe she fell and hit her toe.\n\nWhen Jessica was here we used to play games and dance and pick pretty flowers around the house.  And sometimes we'd hide when we saw daddy coming home, then jump out and surprise him!\n\nCome back, Jessica!  If you come back then maybe daddy will too and we can all play together again...", sourceObjectiveStatus = "unverified-source-field" }
quests[5621] = { id = 5621, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garments of the Moon", description = "I need your help, {name}. I am needed here to train the other students, but you, you can help one of our injured Sentinels just south of Dolanaar. She was hurt patrolling the town and could use our aid. Her name is Shaya.\n\nWhen you find her, heal her wounds, and then fortify her body with your spells. This will at least protect her from harm longer if she finds trouble. Return to me here after you've done your duty to Elune.", sourceObjective = "Find Sentinel Shaya and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Laurna Morninglight in Dolanaar.", completion = "You have done well and you have served Elune. For that, I thank you.\n\nPlease, take this robe as a token of my thanks. It signifies you have earned your place among our order. If you wish, wear it with pride, but either way, we will always recognize you as one of our own.\n\nGo with Elune, {name}, and thank you.", sourceObjectiveStatus = "unverified-source-field" }
quests[5622] = { id = 5622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Favor of Elune", description = "{name}, you must travel to Dolanaar when your business here in Shadowglen is done. There, you will find Laurna Morninglight. She will instruct you further in the ways of Elune, and it is with her that you will earn your first garments denoting your station as a <priest/priestess> of Elune.\n\nTake care, and may you be protected in your journeys.", sourceObjective = "Speak to Laurna Morninglight in Teldrassil.", completion = "I'm happy to see Shanda has sent you to find me, {name}. Teaching young priests the ways of Elune gives me great satisfaction.", sourceObjectiveStatus = "unverified-source-field" }
quests[5623] = { id = 5623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Favor of the Light", description = "Hello again, young <priest/priestess>. The time has come for you to learn more about our religion. After you've completed whatever tasks you have here in Northshire, please seek out Priestess Josetta in Goldshire. She has more to teach you and has heard that you are growing strong in the ways of the Light. She looks forward to tutoring you more.", sourceObjective = "Speak to Priestess Josetta in Elwynn Forest.", completion = "I'm glad you've arrived, {name}. We have much to discuss about your future and your path within the Light.", sourceObjectiveStatus = "unverified-source-field" }
quests[5624] = { id = 5624, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garments of the Light", description = "Normally I put forth a small challenge to followers of the Light to test their skill. I want to see if they are worthy of wearing their first robes--a sign that the church outwardly approves of the <priest/priestess> and supports <him/her>.\n\nBut this situation is a bit different. One of Goldshire's citizens saw an injured guard near the lake to the east of here. His name is Roberts. Find him, heal him, fortify his body and return here. If you can do that for me, then I will consider your test complete.", sourceObjective = "Find Guard Roberts and heal his wounds using Flash Heal.", progress = "As you may have already learned, our healing magics are vital to the survival of our people in these harsh times--especially to adventurers and heroes who take up arms and magic to fight back so many different threats.\n\nYou would do well to always remember how important that skill is. That, coupled with Fortitude, make your companions far more capable in battle since they will be able to stand up to a greater number of blows.\n\nDo not let anyone dismiss how powerful your magics are.", completion = "Excellent, {name}. With one more healthy guard out there to help the town, we'll be that much safer. I'm glad to see you're already learning to use your abilities wisely. If you feel you are ready for more training at any time, please come back to me. But for now, take this robe. It will let others know that you are one of our order. If you don't want to wear it, that's fine. Later there will be more tests and this robe isn't necessary for those.", sourceObjectiveStatus = "unverified-source-field" }
quests[5625] = { id = 5625, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garments of the Light", description = "It's usually about this time that one of your power is tested to see if they're worthy of wearing robes denoting their place in the church. But to be honest, I got more pressing matters to look into. Citizen of Kharanos' just came in here and told me 'bout a hurt mountaineer just outside town to the south--name's Dolf.\n\nYou heal Dolf and give him Fortitude, and I'll consider you done with proving yourself. How's that sound?", sourceObjective = "Find Mountaineer Dolf and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Maxan Anvol in Kharanos.", progress = "Have you found Dolf yet, {name}?\n\nYou've probably already learned this, but our ability to heal is very useful. Not only are we able to take care of the wounded, but we're vital to the survival of all those would-be heroes out there trying to make a name for themselves. With Fortitude to increase the amount of blows we can take, and our healing magic to keep them alive, there's nothing we can't overcome!", completion = "Well done, {name}. You got the Light inside you, that's for sure.\n\nHere, take this robe. It'll denote your role in the church and help people recognize you as a {class}--wear it if you want.\n\nLater, there will be more tests that you'll have to go through. Do what you can to learn about your abilities and what you're capable of. Try your hand at a fight or two alone, and then again with other travelers.\n\nBut don't fret none... you're as powerful as they come.", sourceObjectiveStatus = "unverified-source-field" }
quests[5626] = { id = 5626, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Favor of the Light", description = "Hey! {name}! Got a minute?!\n\nYa been following the Light now for long enough that you find your way to Maxan Anvol in Kharanos. He'll teach ya more about the path yer following, and if you prove worthy, give ya yer first set of robes to denote your station as a <priest/priestess>.\n\nNow get goin'! As soon as yer done here, head through the tunnel--he'll be waitin' for ya.", sourceObjective = "Speak to Maxan Anvol in Dun Morogh.", completion = "Oh, so Branstock sent ya, did he? Good, good! He's right, it is 'bout time you started taking a much larger step into the Light. It'll build character and make ya stronger... an' that's what you'll need more than anything: strength of body... strength of will.", sourceObjectiveStatus = "unverified-source-field" }
quests[5627] = { id = 5627, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stars of Elune", sourceObjective = "You've proven yourself worthy of Elune's attention, {name}. If you feel you're ready, I would very much like to teach you one of her spells unique to our people.", sourceObjectiveStatus = "unverified-source-field" }
quests[5628] = { id = 5628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "Ah, yes, hello, {name}? I'm glad you stopped to talk for a moment. You are a far way from home at such a young age--I admire such ambition. I wish when I was younger I could have mustered the courage to travel the world.\n\nThere was a priestess of your order here looking for you not too long ago. She said it was very urgent you returned to the Temple of the Moon in Darnassus and speak to Priestess Alathea--it had something to do with your training. I wouldn't dally too long if you can help it.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Wonderful, you've returned home, {name}. It always pleases Tyrande and myself when those we've trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5629] = { id = 5629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "Hello again, {name}. I know you've been busy aiding our people, but you must take some time for yourself also. Priestess Alathea sent someone here looking for you. It seems that you've caught the attention of our elders and they feel you are prepared for greater things. Head to the Temple of the Moon in Darnassus and look for Alathea there. She will be waiting. Good luck, and may Elune be with you.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Wonderful, you've returned, {name}. It always pleases Tyrande and myself when those we've trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5630] = { id = 5630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "Hello there, <laddy/lassy>. Good to see you travelin' far and wide to distant lands. No offense meant, but a lot o' your kind don't take well to these cold climates usually. Glad to see you're made of tougher stuff.\n\nNot too long ago one of your priestesses was in here lookin' for you--said somethin' about you finding a Priestess Alathea in the Temple of the Moon back in Darnassus. Said it was important and you should head back there soon.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Wonderful, you've returned home, {name}. It always pleases Tyrande and myself when those we've trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5631] = { id = 5631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "A priestess recently visited our halls seeking you out, young {race}. She said that she was on a mission to find you and that you should return to the Temple of the Moon in Darnassus as soon as possible. When you arrive, seek out a Priestess Alathea--she will tell you more.\n\nThe Light be with you, {name}.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Wonderful, you've returned home, {name}. It always pleases Tyrande and myself when those we've trained go out into the world and return to us safely. How have things been with you? Does Elune still bless your travels? Perhaps after we speak more about the business at hand, you could tell me more of your travels.", sourceObjectiveStatus = "unverified-source-field" }
quests[5632] = { id = 5632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "Oh, yes, of course. Hello, {name}. A messenger from our order was here not too long ago looking for you. She mentioned something important happening back in Darnassus and that you should return to the Temple of the Moon as soon as you can. When you arrive, speak to Priestess Alathea. I believe it has something to do with your progressing so well in our ways.\n\nAgain, return to Darnassus when you can.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5633] = { id = 5633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning Home", description = "Greetings, <laddy/lass>. Good to see you here in our great halls. A blessing be on you and your kind.\n\nWhile you were traveling through our lands, a priestess of your temple came here seeking you. She said that you were to return to the Temple of the Moon as soon as possible. I'm sorry I can't tell you more, but it did sound important. When you get to the temple, speak to a Priestess Alathea.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", sourceObjectiveStatus = "unverified-source-field" }
quests[5634] = { id = 5634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", sourceObjective = "You have done the Light a great service by becoming a shining example to those who travel in these dangerous lands and beyond. Please, accept this lesson as a thanks for all you've done.", sourceObjectiveStatus = "unverified-source-field" }
quests[5635] = { id = 5635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", description = "You've caught the attention of our superiors, {name}. They've asked you travel to the Cathedral of Light in Stormwind as soon as possible. Apparently they feel you've proven yourself already and are prepared to further your training. When you get there, find High Priestess Laurena. She will be able to guide you further. Good luck, and may the Light be with you.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5636] = { id = 5636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", description = "Elune bless you, good {race}. I hope your Light finds you and protects you well this day.\n\nOne of your priests was here not long ago looking for you. He mentioned you returning to the Cathedral of Light as soon as possible to speak with High Priestess Laurena. It seems you've done well to garner such attention. I wouldn't spend too much time here--your people have need of you.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5637] = { id = 5637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", description = "Time's come for you to head to Stormwind, {name}. High Priestess Laurena in the Cathedral of Light wants to speak to you. Gotta be somethin' really good or really bad for the High Priestess to want you there personally, but I'm guessin' you've only done well for yourself and it's a good thing that she wants to speak to ya.\n\nBut don't waste too much time 'round here. I'd head there as soon as you can.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5638] = { id = 5638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", description = "Just a short time ago, one of your priests was here looking for you, {race}. He said that if I were to see you, I should direct you towards the Cathedral of Light. He said it was very important, but I would not be overly concerned if I were you. His demeanor seemed positive... as though it were good news. I wouldn't take too long in making my way there if I were you.\n\nElune be with you, good {race}.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but most importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5639] = { id = 5639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", description = "You're needed in Stormwind, {name}. The High Priestess there, Laurena, says it's time for you to prove you're worthy of the next level of your training. Don't waste too much time finding your way there. You can find her in the Cathedral of Light in the center of the city. Give her my regards, and prove how worthy you are of such a calling. The Light be with you, {name}.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5640] = { id = 5640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desperate Prayer", description = "Praise be to Elune, and to your Light, {name}.\n\nAbout this time, many of our order learn abilities reflecting their faith in Elune. If knowledge serves me, I believe the same holds true for your order also.\n\nWhen your business in Darnassus is complete, I would seek out one of your High Priestesses for further training.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "I'm glad you've arrived, {name}. There are many things we will have to discuss, but more importantly is your training in the ways of the Light.\n\nThere are lessons all servants of the Light must learn. If you are ready, we'll begin discussing some of those now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5641] = { id = 5641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lack of Fear", sourceObjective = "You've got the makings of a great {class}, {name}. Keep up the good work!\n\nYou've already shown you're ready for battle. Perhaps it's time we taught ya a little somethin' more.", sourceObjectiveStatus = "unverified-source-field" }
quests[5642] = { id = 5642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowguard", description = "Something important is up in Orgrimmar, {name}.\n\nThe normal messengers that come through here looking for troll priests usually are very casual. This time, they seemed to be in much more a hurry. Don't dally too long in Thunder Bluff. I'd return to the Valley of Spirits as soon as possible.", sourceObjective = "Speak to Ur'kyo in Orgrimmar.", completion = "One of the most important rites of passage for a {class} of our faith is upon us, {name}. I will explain more to you--you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[5643] = { id = 5643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowguard", description = "Like many of our own priests, your own tribe puts you through rites of passage. These rites often teach priests special abilities that are vital to their survival. I sense that time is upon you even as we speak. You must return to the Valley of Spirits in Orgrimmar and speak to Ur'kyo. What he teaches you might be very important for the future.", sourceObjective = "Speak to Ur'kyo in Orgrimmar.", completion = "One of the most important rites of passage for a {class} of our faith is upon us, {name}. I will explain more to you--you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[5644] = { id = 5644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devouring Plague", description = "Ah, a wonderful day for you, {name}. I can see by the lessons you've learned that the time has come to send you back to Aelthalyste. There are things only she can teach you, and even then, only if you prove worthy.\n\nI will not spoil the surprise for you, but I remember when I was a young priest learning about true power... divine power. Yes, those were the days.\n\nGo back to Aelthalyste in the Undercity, {name}. She will be awaiting you in the War Quarter.", sourceObjective = "Speak to Aelthalyste in the Undercity.", completion = "Good, you've returned, and not a moment too late. We have great things to discuss, {name}. Your abilities are growing stronger, and we must make sure you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[5645] = { id = 5645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lack of Fear", description = "{name}, your High Priest Rohan would have an audience with you in Ironforge. Make haste, my strong friend, your next test quickly approaches. Although I wish I could bear witness to your race's own special rites, my place is here. But may the Light go with you in your travels. Rohan should still be in the Mystic Ward once you reach the city. He will be waiting.", sourceObjective = "Speak to High Priest Rohan in Ironforge.", completion = "It is good you've come, {name}. Our race is proud and strong, and it is time you learn to not only be so yourself, but to invoke such emotion and confidence in others. You prepared, lad?", sourceObjectiveStatus = "unverified-source-field" }
quests[5646] = { id = 5646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devouring Plague", description = "Aelthalyste show our people great respect by sending them back to me for more training, and now I do the same for her tribe.\n\nYou return to the Undercity, {name}. There, in the War Quarter, she be ready to teach you more 'bout your people and their ways. Go there, and do not wait long.", sourceObjective = "Speak to Aelthalyste in the Undercity.", completion = "Good, you've returned, and not a moment too late. We have great things to discuss, {name}. Your abilities are growing stronger, and we must make sure you are ready.", sourceObjectiveStatus = "unverified-source-field" }
quests[5647] = { id = 5647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lack of Fear", description = "Your race is so very strong, {name}. We are proud to call you allies. And as each day's sun sets, you and your kin grow closer to not only finding your true origins, but find great confidence that you are on the right path in so many things. That feeling must make you feel so triumphant.\n\nWord came from Ironforge just recently. It asked that you return there and speak to High Priest Rohan in the Mystic Ward. I would not keep him waiting. May Elune guide your travels.", sourceObjective = "Speak to High Priest Rohan in Ironforge.", completion = "It is good you've come, {name}. Our race is proud and strong, and it is time you learn to not only be so yourself, but to invoke such emotion and confidence in others. You prepared, lad?", sourceObjectiveStatus = "unverified-source-field" }
quests[5648] = { id = 5648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garments of Spirituality", description = "You be ready for your first test, {name}. South of Razor Hill, just outta town, one of our grunts be hurt fightin' off some o' Proudmoore's old troops. She not doin' too well, an' she benefit much if one of our kind could help her. Find her--her name be Kor'ja--heal her wounds, an' give her the blessin' of our ancestors.\n\nYou do this, an' me thinks that be sufficient proof that you ready to move on in our ways.", sourceObjective = "Find Grunt Kor'ja and heal her wounds using Lesser Heal (Rank 2). Afterwards, grant her Power Word: Fortitude and then return to Tai'jin at Razor Hill.", progress = "Most think it logical that healin' magics be powerful, but not many understand how powerful. You can keep many alive when instead they should be meetin' their own ancestors. This healin' magic mixed with the ability of Fortitude are a very powerful combination of spells. You remember this. It helpful to all manner of people: warriors, mages and everything in between.", completion = "Good, then Kor'ja lives and goes off to defend our town from those malicious humans. I often wish to remember days of battle; where power was shown in combat and it was the wise who often destroyed those who relied on just their strength.\n\nYou done good by me, {name}. You take this robe now. Maybe it help, maybe you not care, but you earned it and I'm proud to call you brother.", sourceObjectiveStatus = "unverified-source-field" }
quests[5649] = { id = 5649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Favor of Spirituality", description = "Aye, mon. Our kind have joined the Horde because they be good for us. They loyal, and they teach us much 'bout tings like honor. But our old ways die hard. The orcs may not approve of all our traditions, but that not mean we can't continue to practice some them in secret.\n\nYou know this, an' that's why I send you to Tai'jin in Razor Hill. She teach you more 'bout our history. She teach you the ways of our tribe. Go to her when you be ready.", sourceObjective = "Speak to Tai'jin in Durotar.", completion = "Ahh... so you finally come to Tai'jin. This be good.\n\nYou already know that we are not da same tribe that once joined with the Horde. We be much stronger now. We stronger 'cause we adapt--the Horde teach us that much. We no longer defeat our enemies and gain strength from them; now we gain strength, and then defeat our enemies.\n\nThe difference be subtle, but you will learn. You will see. The tribe count on you to learn such things.", sourceObjectiveStatus = "unverified-source-field" }
quests[5650] = { id = 5650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garments of Darkness", description = "Our power comes from darkness and shadow, {name}, but that is not your only role. You have acknowledged that there is merit in knowing the healing arts. This is wise. But before you can know the dark, you must also know the light. And for this, I have a test for you.\n\nNorth of the cemetery is a wounded Deathguard--Deathguard Kel. He has protected us from gnolls for some time, and needs healing. But, you must also fortify his body before he can return to duty. Do both with your spells, and then return to me.", sourceObjective = "Find Deathguard Kel and heal his wounds using Lesser Heal (Rank 2). Afterwards, grant him Power Word: Fortitude and then return to Dark Cleric Beryl in Brill.", progress = "Our powers make us ideal for so many situations, {name}. You'll find that no matter what though, our ability to mend wounds and increase the amount of damage our companions can take will always be the most desired talents we have access to. Do not let that dissuade you from pursuing other paths as a {class}--you can be effective in many ways. But... if you truly wish to destroy your enemies with magical energy, perhaps the arcane is more to your liking.", completion = "You have passed my test with ease. Good.\n\nSoon, you will be ready to take on more responsibility and that road will lead to darker powers--powers that no {class} of another race has.\n\nTake this robe as a symbol of your station. You have earned it. If you do not wish to wear it, then so be it, you may do with it as you will. I and others like us will always acknowledge you for what you've achieved in our ranks.", sourceObjectiveStatus = "unverified-source-field" }
quests[5651] = { id = 5651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Favor of Darkness", description = "There are many lessons that the Forsaken have learned through experience--things that some races can only begin to fathom. And although our path lies in darkness, you will find that a great many things rely on both the light and the dark. Your lessons shall teach you to use both... and with discretion. But heed my words: never forget we were forged in corruption and left to rot like so much carrion. The Darkness is our home.\n\nSeek out Dark Cleric Beryl in Brill when you're ready to learn more.", sourceObjective = "Speak to Dark Cleric Beryl in Tirisfal Glades.", completion = "Finally, you've arrived. Your faith alone will not allow you to pass the trials before you, young one. A sense of urgency and some ambition will help too.", sourceObjectiveStatus = "unverified-source-field" }
quests[5652] = { id = 5652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex of Weakness", sourceObjective = "You would do well to pay heed to this lesson, young one. The Hex of Weakness will be a great boon to you in battle. Later I will have tests for you to further yourself and prove your worth to the tribe.", sourceObjectiveStatus = "unverified-source-field" }
quests[5654] = { id = 5654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex of Weakness", description = "It be time for you to meet with Ur'kyo, {name}. He be in the Valley of Spirits in the orc city. Go there and speak to him. It is time you learn more of the old ways of our kind. It time you be brought into the circle and made a true priest of our tribe.", sourceObjective = "Speak to Ur'kyo in Orgrimmar.", completion = "Ah, good, you be here now. We can start your training in the old ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[5655] = { id = 5655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex of Weakness", description = "I sent here to make sure that you not wander too far from home, {name}. They send me to make sure you return home because Ur'kyo, greatest of our priests, wish to speak to you. You go there. You go to the Valley of Spirits in the orc city and you speak to Ur'kyo. He wait for you now.", sourceObjective = "Speak to Ur'kyo in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[5656] = { id = 5656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex of Weakness", description = "It always warms my undying heart to see priests from all cultures wander the world. To know that power exists that is not arcane and well within our grasp. That's why it is my honor to direct you home, {name}.\n\nUr'kyo, your great priest in Orgrimmar, has asked for your presence. You can find him in the Valley of Spirits.", sourceObjective = "Speak to Ur'kyo in Orgrimmar.", completion = "Ah, good, you be here now. We can start your training in the old ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[5657] = { id = 5657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hex of Weakness", description = "Home. Return home, young {race}.\n\nYour spiritual leader Ur'kyo begs you to return to him and speak about the path you travel.\n\nGo to the Valley of Spirits in the great Horde city of Orgrimmar. You will find him there.", sourceObjective = "Speak to Ur'kyo in Orgrimmar.", completion = "Ah, good, you be here now. We can start your training in the old ways.", sourceObjectiveStatus = "unverified-source-field" }
quests[5658] = { id = 5658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch of Weakness", sourceObjective = "Ah, young {class}, I am glad you have returned here. I would teach you a lesson you would do well to not forget. Are you prepared?", sourceObjectiveStatus = "unverified-source-field" }
quests[5660] = { id = 5660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch of Weakness", description = "You be far from home, {class}. You be needed there, back in your city under the ground. Your mistress, the one you be callin' Aelthalyste be needin' you back there. Like my tribe, there things you must learn only from her. Don't be stayin' here too long. You should be headin' to the War Quarter as fast as a zeppelin can carry you.", sourceObjective = "Speak to Aelthalyste in the Undercity.", completion = "Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[5661] = { id = 5661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch of Weakness", description = "You be far from home out here in the Bloodhoof Village, {name}. I be sent here to find priests of my own tribe to send back to speak to our leaders, but that not mean I cannot help you too.\n\nI hear word that your head priestess spirit want all Forsaken to come to her--there are things you must learn.\n\nGo to meet Aelthalyste in the War Quarter in that city of yours.", sourceObjective = "Speak to Aelthalyste in the Undercity.", completion = "Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[5662] = { id = 5662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch of Weakness", description = "My respect to you and your kind, {name}. I normally teach only those of my own tribe. Your lessons come from Aelthalyste in the city once called Lordaeron.\n\nYou should return to her if you're to learn those abilities that set you apart from other faiths.\n\nGo to the War Quarter in the Undercity and find your mistress there.", sourceObjective = "Speak to Aelthalyste in the Undercity.", completion = "Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[5663] = { id = 5663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Touch of Weakness", description = "Aelthalyste sent word out to all her priests. We're to direct the younger of our order to the Undercity for more training. If you truly count yourself among our faithful, then you should return there also.\n\nYou can find Aelthalyste in the War Quarter deep in the Undercity.", sourceObjective = "Speak to Aelthalyste in the Undercity.", completion = "Ah, good, another has arrived. Time may not matter to me, but to you it is of the essence. There is much for you to learn and there is much I wish to teach you. You simply must prove your worth. Do that, and you shall be greatly rewarded.", sourceObjectiveStatus = "unverified-source-field" }
quests[5672] = { id = 5672, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Grace", sourceObjective = "By devoting yourself to Elune and our people, you have attained a state that not all of us can achieve. It is tradition that you then be taught even greater abilities for your devotion. Do you accept?", sourceObjectiveStatus = "unverified-source-field" }
quests[5673] = { id = 5673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Grace", description = "You know you have access to any of our trainers at any time, {name}, but there are some things that we cannot pass on to you. One of those things are the teachings of your goddess Elune. She gives special abilities to her faithful, and if I'm not mistaken, it is time for you to return home to your Temple of the Moon to be tested.\n\nReturn there when you can and speak to Priestess Alathea.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Elune bless you for returning so quickly to us. This is an important time in your training, and a time that all of our order take very seriously. When you've rested from your journey here, please, let me know. We can then discuss the continuation of your training and where your path will lead you next.", sourceObjectiveStatus = "unverified-source-field" }
quests[5674] = { id = 5674, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Grace", description = "A wonderful day has come, {name}. You've reached the age in which our <priests/priestesses> are trained in abilities only Night elves know. But it is not for me to train you. You must return to the Temple of the Moon and speak to Priestess Alathea as soon as your business here is concluded. She will test you to ensure you're prepared, and only then will she teach you Elune's Grace.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Elune bless you for returning so quickly to us. This is an important time in your training, and a time that all of our order take very seriously. When you've rested from your journey here, please, let me know. We can then discuss the continuation of your training and where your path will lead you next.", sourceObjectiveStatus = "unverified-source-field" }
quests[5675] = { id = 5675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elune's Grace", description = "Time's a wastin', <lad/lass>. It's time for you to return home to Darnassus. Priestess Alathea's sent word here that you're to return there for training. Seems they feel you're ready to be tested much like those who serve the Light. You should head out whenever you can. Alathea's message said that she'd be waitin' for you in the Temple of the Moon. Good luck.", sourceObjective = "Speak to Priestess Alathea in Darnassus.", completion = "Elune bless you for returning so quickly to us. This is an important time in your training, and a time that all of our order take very seriously. When you've rested from your journey here, please, let me know. We can then discuss the continuation of your training and where your path will lead you next.", sourceObjectiveStatus = "unverified-source-field" }
quests[5676] = { id = 5676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Feedback", sourceObjective = "We were forced to learn some magics to protect us from what is commonly called our greatest enemy: the arcane.\n\nI would teach you a spell to help you defend yourself and your companions from those who would wield such power.", sourceObjectiveStatus = "unverified-source-field" }
quests[5677] = { id = 5677, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Feedback", description = "As much as I'd like to show you our own special teachings of the Light, it is not our place. Your place is back in Stormwind with your own kind, {name}... for now. Believe me, I mean no offense. When you return to High Priestess Laurena in the Cathedral of Light you'll understand what I'm talking about--the time has come for your race to prepare you for the future; to separate yourself from others that follow a similar path.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "Ah, you have wonderful timing, {name}. I was beginning to wonder if all of my messengers had been successful. I'm glad to see they were, otherwise I would wager you'd still be out in the world learning more about all the threats that exist against our people.\n\nAre you ready? Ready for more training I mean. You're growing in power more quickly, and I feel you are ready to learn more about our faith.", sourceObjectiveStatus = "unverified-source-field" }
quests[5678] = { id = 5678, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Feedback", description = "It is time for you to return to Stormwind, young one. Your superiors there have called you back for more training. And although it disturbs me some, your race and mine are allies and I would not betray that.\n\nI do not mean to be so coy with you--my distrust of arcane magics, be they divine inspired or not, is still strong within me.\n\nYou will know of what I speak after you return to your Cathedral of Light. Speak to High Priestess Laurena when you arrive.", sourceObjective = "Speak to High Priestess Laurena in Stormwind.", completion = "Ah, you have wonderful timing, {name}. I was beginning to wonder if all of my messengers had been successful. I'm glad to see they were, otherwise I would wager you'd still be out in the world learning more about all the threats that exist against our people.\n\nAre you ready? Ready for more training I mean. You're growing in power more quickly, and I feel you are ready to learn more about our faith.", sourceObjectiveStatus = "unverified-source-field" }
quests[5679] = { id = 5679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Devouring Plague", sourceObjective = "I would teach you Devouring Plague if you feel you are prepared, {name}. A spell of no small power, it will aid you in your coming battles. Practice with it--there will be tests later.", sourceObjectiveStatus = "unverified-source-field" }
quests[5680] = { id = 5680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowguard", sourceObjective = "Your rites will come soon enough. For now, I teach you a spell that will be of great use to you when you do battle with your enemies.", sourceObjectiveStatus = "unverified-source-field" }
quests[5713] = { id = 5713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Shot. One Kill.", description = "I was traveling to Lor'danel with an important message when I was attacked by the furbolg Marosh and his trackers. During the attack I was poisoned, leaving me barely able to stand. I can make an antidote, but it will take time before it is ready.\n\nI would ask that you defend me until I can apply the antidote. I will aid you with my bow as best I can.\n\nShould we survive, I will be able to deliver my message to Lor'danel, while you speak with Onaeya at Maestra's Post to inform her of this incident.", sourceObjective = "Protect Sentinel Aynasha, then speak with Onaeya at Maestra's Post in Ashenvale.", completion = "You bring most welcome news {class}. It is good to hear that Aynasha is alive and well thanks to you. I would hope that you might accept a reward for your valor. May Elune watch over you and light your path.", sourceObjectiveStatus = "unverified-source-field" }
quests[5721] = { id = 5721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle of Darrowshire", description = "Now, {name}, you will take part in battle of Darrowshire, and you will save Joseph Redpath.\n\nPlace this relic bundle in the Darrowshire town square, and the spirits of Darrowshire will rise.  Join their battle and assure that these two things come to pass: Davil must survive beyond the death of Horgus, and Redpath must survive to be corrupted, then defeated.\n\nAfter defeating the corrupted Redpath, his spirit will be saved.  Speak with him, then return to his daughter Pamela.", sourceObjective = "Place the Relic Bundle at the Darrowshire town square.\n\nPrevent Davil Lightfire's death until the death of Horgus.\n\nPrevent Captain Redpath's death until Redpath the Corrupted appears.\n\nDefeat Redpath the Corrupted.\n\nSpeak with the spirit of Joseph Redpath when he appears at the town square, then speak with Pamela at her home.", progress = "I think I heard ghosts outside.  They whisper scary things to me...", completion = "The fighting is over!  I heard my daddy whisper to me.  He scared away all the ghosts and he says he's coming home!  I'm so happy!\n\nHe also said I should welcome you if came to our house, so I made some tea!\n\nI hope you like lots of sugar!", sourceObjectiveStatus = "unverified-source-field" }
quests[5722] = { id = 5722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching for the Lost Satchel", description = "The troggs are not the only thing that interested Magatha in Ragefire Chasm. She has heard word that one of her servants, a Maur Grimtotem, found something peculiar while in the Chasm, but he never made it out to show her what. She'd like Maur's body found--if it still exists--and any signs of what he found while attempting to speak to the troggs.\n\nReturn to Magatha any items of interest, and I'm sure she would be very generous in her reward.\n\nAgain, seek the Chasm in the darkest areas of Orgrimmar.", sourceObjective = "Search Ragefire Chasm for Maur Grimtotem's corpse and search it for any items of interest.", completion = "The body looks seriously beaten by clubs or fists, but most of the corpse's clothing and equipment still looks present. It seems the troggs do not overly care much for material wealth.\n\nYou begin to search the body for anything of interest that might help Magatha.", sourceObjectiveStatus = "unverified-source-field" }
quests[5723] = { id = 5723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Testing an Enemy's Strength", description = "Beneath the city of Orgrimmar, stout creatures known as troggs started coming to the surface from deep below the lava filled tunnels. In her ever-benevolence, Magatha sought to make peace with the creatures, but they turned on her diplomats, killing them. She will not allow such treatment of the tauren people and now consider the creatures a threat to all of the Horde.\n\nShe asks that you put an end to this trogg threat before it overwhelms the Horde from below. Find Ragefire Chasm and destroy them all.", sourceObjective = "Search Orgrimmar for Ragefire Chasm, then kill 8 Ragefire Troggs and 8 Ragefire Shaman before returning to Rahauro in Thunder Bluff.", completion = "I am glad to see you took Magatha's task seriously. Thank you, {name}. I'm sure the troggs will have a harder time coming to the surface with their numbers so greatly reduced.\n\nPerhaps in the future we can take time to figure out where such creatures came from, and what they really want.", sourceObjectiveStatus = "unverified-source-field" }
quests[5724] = { id = 5724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Returning the Lost Satchel", description = "You find a satchel under the body of the tauren. It is still gripped tightly in his arms as though he was trying to protect it while being attacked by the troggs.\n\nRemoving the satchel from his vice-like grip, you stow it with your own equipment and prepare to make your way out of the tunnels and back to Rahauro in Thunder Bluff.", sourceObjective = "Take the Grimtotem Satchel to Rahauro in Thunder Bluff.", progress = "Were you able to find anything, {name}? Any clues as to why one of her clansman had to die needlessly would be helpful.", completion = "Excellent, {name}. Thank you.\n\nMagatha told me that if you were successful in finding her clansman that you be given this. Please, take it in thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[5725] = { id = 5725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Power to Destroy...", description = "Many denizens of the Legion bestow gifts on their followers as you may well know. Some of these gifts the Dark Lady feels would be better off in her hands than in the hands of those with... lesser vision.\n\nA sect of the Shadow Council hidden in caverns below Orgrimmar known as the Searing Blade are a prime example. The Lady tells me that members of the Searing Blade have come into the possession of two powerful spell books--she would like to \"borrow\" these books from them. You will get them for her.", sourceObjective = "Bring the books Spells of Shadow and Incantations from the Nether to Varimathras in Undercity.", progress = "There are a hundred other tasks awaiting my attention, {class}. Do you have the books?", completion = "Good, {class}. You have done well in serving the Dark Lady. Your continued perseverance and ambition will be of great use to the Lady's subjects. Return to me again in the future. Perhaps I will have other tasks for you that will aid the Dark Lady in her attempts at overtaking the Lich King and completely freeing the Scourge.", sourceObjectiveStatus = "unverified-source-field" }
quests[5726] = { id = 5726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Enemies", description = "One thing I will not tolerate are traitors in our midst, {name}. But I would be a fool to play my hand so early--it would not sufficiently cut the corruption out of our lands and only cause the infection to grow worse.\n\nBut you, a young adventurer, could go places my agents could not... could learn the truth... could find the true head of the beast.\n\nIf you are brave enough, then enter Skull Rock to the east of Orgrimmar, find a lieutenant's insignia off one of the Burning Blade there, and return to me.", sourceObjective = "Bring a Lieutenant's Insignia to Thrall in Orgrimmar.", progress = "Do you have the insignia yet, {name}?\n\nIt will be a vital tool in infiltrating what I believe is the greatest threat to the Horde, and finally finding peace in our new home.\n\nYou will learn how intricate a web men and orcs alike can weave when they are motivated by greed and power. The hidden agendas, the corruption, all of it will become clear. You will find yourself in the midst of a war you never knew existed.", completion = "Good, {name}! The spirits be praised, perhaps you are the one who will finally put my greatest fears to rest! Who would suspect someone so young and so brave would rise up and champion our cause? You remind me of myself when I was younger. I will ensure that you are justly rewarded for your efforts if we both survive the coming storm.\n\nBut there is time for more praise later. You've not accomplished anything in comparison to what you will face... but this is a good start.", sourceObjectiveStatus = "unverified-source-field" }
quests[5727] = { id = 5727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Enemies", description = "Now let us see if this insignia you found is worth the effort.\n\nThere is a warlock within the city who believes he has my trust. He does not know that I realize where his true loyalties lie. He is in fact the leader of the Burning Blade. But do not rush off to do battle with him; he has a purpose, and we shall use him against our enemies.\n\nTake this insignia to him in the Cleft of Shadow here in Orgrimmar, speak to him and see if he believes you are one of his own, then return to me here.", sourceObjective = "Take the Lieutenant's Insignia to Neeru Fireblade and speak to him. Gauge if he believes you are a member of the Burning Blade and then return to Thrall in Orgrimmar.", progress = "Well, {class}? Does he believe our ploy, or are things worse than I had first estimated?\n\nProving valuable to Neeru will make our infiltration of the Shadow Council much easier. He will have plenty of information that we can use to route out those who would destroy all we have built in Durotar.", completion = "Excellent! Most excellent, {class}!\n\nWhat you have done this day is only the first step in a much broader foundation--a foundation that we will build the destruction of the Shadow Council on, once and for all.\n\nTell me all he said... and leave not one word out--it may be more important than you realize.", sourceObjectiveStatus = "unverified-source-field" }
quests[5728] = { id = 5728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Enemies", description = "Hmm, leaders of the Searing Blade... this concerns me most. If they are the ones of value to Neeru, then those are who we must target first. This satyr... Bazzalan, and the other Neeru mentioned--what was he, a warlock?--must be slain.\n\nReturn to the Cleft of Shadow and enter Ragefire Chasm, {name}. Find these two leaders of the Searing Blade, and kill them. But be careful not to let Neeru know it was you who did this. You must retain your identity as one of his <brothers/sisters> in arms.", sourceObjective = "Kill Bazzalan and Jergosh the Invoker before returning to Thrall in Orgrimmar.", completion = "I am glad you've returned, {name}. Some of those loyal to me brought word immediately that the caverns below Orgrimmar were in disarray now that their leaders have been slain. I even heard reports that Neeru was more than agitated. It seems we've put a dent in his armor. I can't say I'm displeased... even with such a minor victory.", sourceObjectiveStatus = "unverified-source-field" }
quests[5729] = { id = 5729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Enemies", description = "I think our next step should be to have you placed close to Neeru. If he is as agitated as reports suggest, then we may accomplish two things. One, you may be able to gain some greater knowledge about the Council or at least the Burning Blade, and two, he may just begin to trust you enough that he asks you to start to aid him. He may very well look at you as someone who can fill the void now that some of the leadership is in turmoil.\n\nReturn to the Cleft and speak to him again, but do not be too overt.", sourceObjective = "Speak to Neeru Fireblade in Orgrimmar.", completion = "What is it?! Oh, you, {class}... my apologies. My anger rivals that of a rabid kodo bull... but perhaps it is my own fault. In sending travelers into Ragefire Chasm, I should have seen the possibility that some harm would come from it. It seems both Bazzalan and Jergosh were taken unaware and slain by some of Thrall's do-gooders. A most inopportune time, but there is nothing that can be done about it now.", sourceObjectiveStatus = "unverified-source-field" }
quests[5730] = { id = 5730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Enemies", description = "You are one of my lieutenants! Prepare yourself, {class}. I will call upon you soon.\n\nMy time spent on the Searing Blade may be all but wasted now, but that does not mean that the Shadow Council's schemes elsewhere must suffer. I will do what I can to minimize the damage here in Ragefire Chasm. In the meantime, I will have my agents in the Barrens and Ashenvale begin work on our newest agenda. Return to me soon.", sourceObjective = "Speak to Thrall in Orgrimmar and tell him what you've learned.", completion = "Ashenvale? Hmm, I had not heard of any presence of the Council or the Burning Blade in Ashenvale. My spies will investigate, {name}. You have done well.\n\nFor now, rest, and keep yourself occupied with other tasks. I will call upon you again soon.\n\nLok-Tar Ogar!", sourceObjectiveStatus = "unverified-source-field" }
quests[5741] = { id = 5741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sceptre of Light", description = "The Burning Blade in Thunder Axe Fortress to the east is rumored to have acquired the Sceptre of Light from the Naga. Legend tells that the sceptre is able to sink entire cities under the great seas. The Burning Blade must not be allowed to possess such power.\n\nTo that end, you must retrieve the sceptre yourself!  It is held by a Burning Blade seer, who studies the sceptre from atop one of the Thunder Axe watchtowers.", sourceObjective = "Get the Sceptre of Light and then return it to Azore Aldamort at the tower in Ethel Rethor.", progress = "Do you have the Sceptre of Light?", completion = "The elusive Sceptre of Light!  Your acquisition of it has removed a grave threat to the world.  Well done, {class}, well done.", sourceObjectiveStatus = "unverified-source-field" }
quests[5742] = { id = 5742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redemption", description = "You have worked hard, friend. Rest your weary bones and allow me to properly introduce myself.", sourceObjective = "Listen to what Tirion Fordring has to say.", progress = "Please, friend; sit and hear my tale.", completion = "The Fordring redemption will be a difficult task. Are you prepared?", sourceObjectiveStatus = "unverified-source-field" }
quests[5761] = { id = 5761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slaying the Beast", description = "The primary task set upon me by our great Warchief is to root out the creatures responsible for infesting our lord's great city with demonic influence. The Burning Blade is one threat, but there are others; the Searing Blade for instance, who make their home in Ragefire Chasm, secretly attempting to subvert innocent members of the Horde.\n\nIf they are to be stopped, then their leader must be slain--a Felguard named Taragaman the Hungerer.\n\nKill him, and his heart will appease Thrall, of this I'm sure.", sourceObjective = "Enter Ragefire Chasm and slay Taragaman the Hungerer, then bring his heart back to Neeru Fireblade in Orgrimmar.", progress = "Have you killed the beast? He surely must be the leader of the Searing Blade in Ragefire Chasm.", completion = "Ha! You've done it! Thrall will be so pleased.\n\nI will ensure this heart is taken care of properly.\n\nFor now though, you must celebrate your victory. I will inform Thrall of your success.\n\nThank you for your aid, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[5762] = { id = 5762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hemet Nesingwary Jr.", description = "I have a package for a new customer of mine, a dwarf named Hemet Nesingwary Jr..  The package took weeks to arrive, and Hemet's long gone by now.  He said he was going to Stranglethorn to take his father's place and hunt the beasts there, but he left me some money to send his delivery when I could.  \n\nJunior's a rich dwarf and it's a good idea to keep up relations with the rich ones, yeah?  So... you want to deliver the package for me?\n\nI heard he has a camp in Stranglethorn, north of Grom'gol.", sourceObjective = "Take Kravel's Crate to Hemet Nesingwary Jr. in Stranglethorn Vale.", progress = "Is that desert dust on your collar?\n\nHm... if my nose tells true, I'd say it's not desert dust, it's desert salt!   Been to the Shimmering Flats, have you?", completion = "Great, my package from Koalbeard!  Thank you {name}.  This crate holds special-gauge ammunition, and it'll serve us well out in the jungle!\n\nHere's your pay, and tell me, how is crusty old Kravel these days?  Still up to no good I'd wager...", sourceObjectiveStatus = "unverified-source-field" }
quests[5763] = { id = 5763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting in Stranglethorn", description = "Long ago, a dwarf came to this land.  His name was Hemet and he wished to hunt great beasts.  His skills with the rifle were uncanny, and we spent many days hunting together.  Even the enmity between our peoples was forgotten.\n\nWhen he left for Stranglethorn, I vowed to one day welcome him back.  Now he has gone on to hunt in lands unknown, but his son has taken his place.\n\nTake this kodo horn as a gift to Hemet Jr..  You will find him in Stranglethorn, north of the Grom'gol Base camp.", sourceObjective = "Bring Roon's Kodo Horn to Hemet Nesingwary Jr. in Stranglethorn.", progress = "Sit, {class}.  Soon enough you'll strike back into the jungle.", completion = "Ah, this horn belongs to a Tauren, Roon Wildmane.  He and I had a good time hunting the beasts of Desolace.  So Roon is inviting me back, is he?\n\nWe're neck deep in the jungle right now, but thank you, {name}.  Perhaps my next expedition will take me back to Desolace, the land of the centaurs.", sourceObjectiveStatus = "unverified-source-field" }
quests[5781] = { id = 5781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Forgotten Memories", description = "To help Taelan regain what he has lost, you must gather items from his past.\n\nThe first such item is a toy that I gave to him on his 7th birthday. It was his most cherished possession: A miniature war hammer; an exact replica of my very own.\n\nAfter I was banished for treason, his mother told him that I had died. He was taken to my false grave at the Undercroft, where he buried the hammer along with my memory - forever.\n\nYou must venture to the Undercroft and recover Taelan's hammer.", sourceObjective = "Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective.", progress = "He must be redeemed.", completion = "<Tirion blinks to hold back tears.>\n\nIt was destiny that we meet, {name}. You have blessed me with your kindness.", sourceObjectiveStatus = "unverified-source-field" }
quests[5801] = { id = 5801, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Plume Forged", description = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Arbington again.", sourceObjective = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\n\nBring the Unfinished Skeleton Key to Alchemist Arbington at Chillwind Point, Western Plaguelands.", progress = "Do you have the stem of the skeletal key finished?  I'm sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge.  Once you hand me the unfinished key, you'll be ready for the final item needed to complete its construction.\n\nIt won't be easy at all, but the work you've done to date in preparing for an assault on Andorhal will now start to pay for itself.  You'll see.", completion = "We've got quite the costly skeleton key there, don't we {name}?  Still, it remains unfinished; the time has now come to put some focus behind our creation.  To that end, you're going to have to face the ultimate foe we've been working towards facing in Andorhal... the nefarious being that runs the show within the ruined city walls.\n\nI'm speaking of Araj the Summoner - a lich, and one of the most powerful beings the Scourge calls as its own.", sourceObjectiveStatus = "unverified-source-field" }
quests[5802] = { id = 5802, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Plume Forged", description = "You need two bars of thorium and a powerfully hot heat source to forge the key stem.  You're on your own for the thorium, but I can help with the heat.\n\nTo our west in Un'Goro Crater is Fire Plume Ridge - a simmering volcano.  The lava lake up top is hot enough to fuse thorium and bone together.  Your gold has bought you a mold that simply requires you to dip it in the lake up top; the lava will take care of the rest.\n\nThat's it on my end.  To finish your key, you'll need to talk to Dithers again.", sourceObjective = "Take the Skeleton Key Mold and 2 Thorium Bars to the top of Fire Plume Ridge in Un'Goro Crater. Use the Skeleton Key Mold by the lava lake to forge the Unfinished Skeleton Key.\n\nBring the Unfinished Skeleton Key to Apothecary Dithers at the Bulwark, Western Plaguelands.", progress = "Do you have the stem of the skeletal key finished?  I'm truly sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge.  Once you hand me the unfinished key, you'll be ready for the final item needed to complete its construction.\n\nIt won't be easy at all, but the work you've done to date in preparing for an assault on Andorhal will now start to pay for itself.  You'll see.", completion = "We've got quite the costly skeleton key there, don't we {name}?  Still, it remains unfinished; the time has now come to put some focus behind our creation.  To that end, you're going to have to face the ultimate foe we've been working towards facing in Andorhal... the being that runs the show within the ruined city walls.\n\nI'm speaking of Araj the Summoner - a lich, and one of the most powerful beings the Scourge calls as its own.", sourceObjectiveStatus = "unverified-source-field" }
quests[5803] = { id = 5803, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj's Scarab", description = "Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.\n\nMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!\n\nThe Key to Scholomance awaits, {name}!", sourceObjective = "Destroy Araj the Summoner and bring Araj's Scarab to Alchemist Arbington at Chillwind Point, Western Plaguelands.", progress = "You've come this far {name} - only the destruction of the physical form of Araj the Summoner will provide us with the means to finish the key.  Get Araj's scarab by whatever means necessary and bring it to me - I will fuse it on as the head of the key.", completion = "Yes, this is it!  I... again, I'm absolutely amazed at the depths of your heroism.  It simply boggles the mind the lengths you are willing to go to achieve victory over the forces of darkness.\n\nAllow me now to play my small part in this.  I've prepared a special solvent that should allow me to secure the scarab on as the head of the key, infusing it with the power to breach the locked door of Scholomance.\n\nHere goes nothing...", sourceObjectiveStatus = "unverified-source-field" }
quests[5804] = { id = 5804, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj's Scarab", description = "Araj the Summoner lords over Andorhal from the ruined city's heart.  We know that he was the former leader of Scholomance before claiming the city as his own.  To finish the key, we will need his signet - called a scarab - mounted as the head of the key.\n\nMake your way into the heart of Andorhal, and break his hold on the city now that he is drawn into the open.  Once destroyed, seize his scarab from his fallen phylactery!\n\nThe Key to Scholomance awaits, {name}!", sourceObjective = "Destroy Araj the Summoner and bring Araj's Scarab to Apothecary Dithers at the Bulwark, Western Plaguelands.", progress = "You've come this far {name} - only the destruction of the physical form of Araj the Summoner will provide us with the means to finish the key.  Get Araj's scarab, by hook or by crook, and bring it to me - I will fuse it on as the head of the key.", completion = "Yes, this is it!  I... again, I'm absolutely amazed at the depths of your cunning and bravery.  It simply boggles the mind the lengths you are willing to go in order achieve victory.\n\nAllow me now to play my small part in this.  I've prepared a special solvent that should allow me to secure the scarab on as the head of the key, infusing it with the power to breech the locked door of Scholomance.\n\nThis should take just a moment...", sourceObjectiveStatus = "unverified-source-field" }
quests[5805] = { id = 5805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Merissa Stilwell in Goldshire.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Goldshire Gift Voucher to Merissa Stilwell in Goldshire.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[5821] = { id = 5821, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodyguard for Hire", description = "Under normal circumstances, Rigger and I would lead our kodo past the Kolkar Centaur. Every now and then we hear the Centaur war drums, and when we hear those we stop. It's not good for business to be dead!\n\nI'll tell you what {class}, if you protect us past the Kolkar village we'll make it worth your while.\n\nIt's just a short distance, all you need to do is keep the caravan intact and you can pick up your reward from Smeed Scrabblescrew - he is down the road a bit. We do a little business together.", sourceObjective = "Escort the Gizelton Caravan past the Kolkar Centaur village. Talk with Smeed at Scrabblescrew's Camp for your reward.", completion = "You know, it doesn't seem prosperous to be paying the likes of you to guard Gizelton Caravan. {class}, if I were a bit taller I could take on a second job and sit kodo-side-saddle with the biggest gun my hands could carry... and I'd show them blasted centaur who's their papa.", sourceObjectiveStatus = "unverified-source-field" }
quests[5841] = { id = 5841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Yori Crackhelm in Kharanos.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Kharanos Gift Voucher to Yori Crackhelm in Kharanos.", progress = "Hello!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[5842] = { id = 5842, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Orenthil Whisperwind in Dolanaar.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Dolanaar Gift Voucher to Orenthil Whisperwind in Dolanaar.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[5843] = { id = 5843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Magga in Razor Hill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Razor Hill Gift Voucher to Magga in Razor Hill.", progress = "Hello!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[5844] = { id = 5844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Vorn Skyseer in Bloodhoof Village.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Bloodhoof Village Gift Voucher to Vorn Skyseer in Bloodhoof Village.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[5845] = { id = 5845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Lost Honor", description = "The Order of the Silver Hand was utterly decimated when Uther was slain.\n\nThe boy held out for as long as he could. Pushed to the war torn hamlet of Northdale, he made his final stand.\n\nWere any of the Order left alive, he thought - and did it matter?\n\nIt was with that thought that Taelan threw down the standard of the Order and renounced all that he had known. His honor left upon the blood soaked ground of Northdale.\n\nYou must travel to Northdale and recover that symbol of lost honor.", sourceObjective = "Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective.", progress = "My faith will guide you, {name}. The Light knows no bounds.", completion = "It is as glorious now - even in its tattered state - as the day I looked upon it and took my oath of allegiance.\n\nHis redemption comes and perhaps mine with it...", sourceObjectiveStatus = "unverified-source-field" }
quests[5846] = { id = 5846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Love and Family", description = "When Taelan was a child, we would oft visit Caer Darrow on family excursions. On our last visit, an artist by the name of Renfray painted a portrait of us poised along the beachside. It is my fondest memory of both Taelan and Karandra. For it was at that moment, with my wife and son in my arms, that I felt a bond of love and family that I would never know again.\n\nIf this painting still exists, you must find it.\n\nTravel to the ruined island of Caer Darrow and see if the painting or the artist remain.", sourceObjective = "Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting.", completion = "How could I forget? Many of the spirits on this island are cursed to relive their last happy memory before they met their tragic end.\n\nI too am cursed, but not as they - I am one of the few that remembers all...\n\nPerhaps this thing that you ask me is why I haunt these ruins. Perhaps this thing I tell you shall set me free.", sourceObjectiveStatus = "unverified-source-field" }
quests[5847] = { id = 5847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome!", description = "Welcome to the World of Warcraft!\n\nAs special thanks for purchasing the World of Warcraft Collector's Edition, turn in this gift voucher to Claire Willower in Brill.  You'll then be given a gift: a little companion to join you on your quest for adventure and glory.\n\nThanks again, and enjoy your stay in the World of Warcraft!", sourceObjective = "Bring the Brill Gift Voucher to Claire Willower in Brill.", progress = "Greetings!  It is a pleasure to meet you!\n\nI see you have a special voucher.  Give it to me and I will offer you something in exchange.", completion = "You are indeed a special hero, {name}. We welcome you to the world of Azeroth, and offer you one of these unique gifts!", sourceObjectiveStatus = "unverified-source-field" }
quests[5848] = { id = 5848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Love and Family", description = "The painting... It hung on the wall of my workshop - inside the Order's barracks - for years.\n\nAfter Tirion's trial was over, I knew that I could no longer keep the painting visible. I hid it in a place that they would never think to look.\n\nTravel to Stratholme and make your way deep inside what is now the Scarlet Bastion, search for a painting of our twin moons. Chip away at the paint until you uncover my master work, 'Of Love and Family.'\n\nMay the Light guide your actions.", sourceObjective = "Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world.\n\nReturn the painting to Tirion Fordring.", progress = "The painting, {name}. Do you have the painting?", completion = "<Tirion nearly collapses when he sees the painting.>\n\n<He begins to sob in an almost frenetic manner.>", sourceObjectiveStatus = "unverified-source-field" }
quests[5861] = { id = 5861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Myranda", description = "{name}, you have done all that I have asked thus far. Only one step remains in your quest of redemption.\n\nYou must deliver the items you have collected to Taelan. Unfortunately, Taelan and his Scarlet Crusaders will attack you on sight.\n\nThere is only one way in which to deliver my message and that is through a guise of deception.\n\nTo the south you will find Uther's tomb. An old and trusted confidant of mine, Myranda, now resides there - seek her out. Show her the items and she will assist you.", sourceObjective = "Travel to Uther's Tomb, located in the southern Plaguelands. Show Myranda the HagTirion's Gift.", progress = "I knew this day would come.", completion = "I was Tirion's most trusted advisor when he held rank as Lord of Mardenholde. I openly dissented the verdict passed by the Order of the Silver Hand and was banished for my insolence.\n\nHe has been through much heart ache and disappointment in his life, {race}. Are you prepared to right the wrongs set upon the Fordrings?", sourceObjectiveStatus = "unverified-source-field" }
quests[5862] = { id = 5862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarlet Subterfuge", description = "I am what you would call, an illusionist. Though I may be able to create an illusion to allow you entry into Hearthglen, be warned; my powers have their limitations.\n\nShould you travel too far from these lands, the effects of the illusion will cease. The spell itself takes a great amount of concentration and power from me, and thus, I can only sustain the effect for a short time.\n\nSpeak to me again when you are ready.", sourceObjective = "Speak to Myranda to gain the Scarlet Illusion. Travel to Hearthglen while under the Scarlet Illusion and deliver Tirion's Gift to Highlord Taelan Fordring.\n\nHearthglen is to the north, Taelan should be inside of Mardenholde Keep.", progress = "Are you the reinforcements from Tyr's Hand?", completion = "What is this, soldier?\n\n<Taelan opens the box and begins to examine its contents.>\n\nThis... this cannot be true. But all that you have shown me...\n\n<Taelan falls to one knee, his heartbeat quickens. The fury of ages is about to be loosed upon this town.>", sourceObjectiveStatus = "unverified-source-field" }
quests[5863] = { id = 5863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dunemaul Compound", description = "Just recently, a large band of nomadic ogres arrived in Tanaris. South of here, they have taken over a large area of the desert and formed a compound. Several smaller bands are currently wandering the desert, some of which have invaded the old troll ruins.\n\nThe Dunemaul Compound must be destroyed! We cannot allow these ogres to build up a force.\n\nThe leader of this band is named Gor'marok the Ravager; I believe that putting an end to his leadership will be the beginning of the end for the ogres.", sourceObjective = "Andi Lynn in Gadgetzan wants you to destroy the Dunemaul Compound by killing 10 Dunemaul Brutes, 10 Dunemaul Enforcers, and Gor'marok the Ravager.", progress = "I'm so worried! Please be careful!", completion = "I'm so glad you were able to do this for me, {name}! Thanks for your help!", sourceObjectiveStatus = "unverified-source-field" }
quests[5881] = { id = 5881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Calling in the Reserves", description = "The Horde does well keeping our troops fresh... since the Great War we have been prosperous here in Kalimdor.\n\nI need you to do me a favor, I have a lad by the name of Grish Longrunner protecting the Great Lift in the southern barrens. Give him this letter; the letter will let him know that I have a reserve warrior coming to relieve him of duty so that he can visit his family. He requested this sometime ago and he would be happy to hear the news.", sourceObjective = "Maggran wishes you to deliver a letter to Grish Longrunner at the Great Lift in the Barrens.", progress = "You have news from Maggran Earthbinder?", completion = "This is great news; I have been sitting here guarding this hunk of wood for too long. Now I can spend some time with my family... Yippee!", sourceObjectiveStatus = "unverified-source-field" }
quests[5882] = { id = 5882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Hunting", progress = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves.  Scour Felwood for corrupted plants, {name}!  Wherever they are, use the salve I have given you to purify them." }
quests[5883] = { id = 5883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Mining", progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve.  If you find more vitriol when you mine in Felwood, remember to hold on to it for me!  The more of it you find, the more salve I will be able to make." }
quests[5884] = { id = 5884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Gathering", progress = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", completion = "Excellent work {name} - every bit of this, once we purify it, will help us take back Felwood.  Here, take some doses of Cenarion plant salve and head into the forest.  The reclaiming of the land from the corruption waits for no {race}!" }
quests[5885] = { id = 5885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Skinning", progress = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", completion = "This is exactly what I need.  Here - take these plant salves and use them to reclaim Felwood from the corruption.  We must persevere, {name}!" }
quests[5886] = { id = 5886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Disenchanting", progress = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, {name}.  Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were.  If you need more salve, then find me here!" }
quests[5887] = { id = 5887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Hunting", progress = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves.  Scour Felwood for corrupted plants, {name}!  Wherever they are, use the salve I have given you to purify them." }
quests[5888] = { id = 5888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Mining", progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve.  If you find more vitriol when you mine in Felwood, remember to hold on to it for me!  The more of it you find, the more salve I will be able to make." }
