quests[5891] = { id = 5891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salve via Disenchanting", progress = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, {name}.  Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were.  If you need more salve, then find me here!" }
quests[5892] = { id = 5892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irondeep Supplies", description = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep.\n\nWe need the supplies in Irondeep, {name}.  Enter the mine and bring me a load of them.", sourceObjective = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.", progress = "Do you have the supplies, {name}?  We can never have enough!", completion = "Well done!  I'll put these supplies to good use!  Thanks, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[5893] = { id = 5893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coldtooth Supplies", description = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...\n\nBut we still need our supplies, {name}!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...", sourceObjective = "Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep.", progress = "Have you been to the Coldtooth mine, {name}?  Do you have the supplies I asked for?", completion = "Ah, you got  them.  Good work, {name}!  These supplies are a little musty from sitting in that dark mine for so long, but we'll make use of them nonetheless.\n\nThank you, {name}.  Your deeds are vital to the maintenance of our fighting forces.", sourceObjectiveStatus = "unverified-source-field" }
quests[5901] = { id = 5901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague Upon Thee", description = "So, to bring pain and strife to the Scarlet Crusade, I want to take their precious lumber mill from them. I'm sure the loss of such a resource will cause them a great deal of harm in defending and rebuilding the town for their own reasons. Will you help me, {name}?\n\nStart by taking this jar to Plaguewood in the Eastern Plaguelands. Fill it with the termites you find in their mounds throughout the woods. Come back when you have enough.", sourceObjective = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.", progress = "Do you have the termites yet, {name}? I am sure it is obvious to a smart {class} like yourself.\n\nOnce we have enough of them, we'll make sure no one can use the lumber mill ever again!", completion = "These will do nicely, {name}. Thank you.\n\nIf you're ready, we can get on with the next step.", sourceObjectiveStatus = "unverified-source-field" }
quests[5902] = { id = 5902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague Upon Thee", description = "Now that we have plenty of termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; someplace high, like on a crate or something.\n\nAfter you open it, the rest should take care of itself. Just come back here and I'll reward you for helping me.", sourceObjective = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\n\nProvided item:", completion = "The termites are obviously getting restless as you place the barrel on top of the crate.", sourceObjectiveStatus = "unverified-source-field" }
quests[5903] = { id = 5903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague Upon Thee", description = "I've tried many times to rout out the Scarlet Crusade through force alone, but to no avail. So, as an alternative, I've decided to make their lives more difficult.\n\nIf you are willing to help, I want to infest that lumber mill with the most terrible species of termites ever found.\n\nIn Plaguewood, near the once-great Stratholme, there is a breed that survived the plague and the Scourge combined. Find their mounds and fill this jar with them, so we can prepare them to be unleashed on the Crusade.", sourceObjective = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", progress = "Did you find the termite mounds, {name}? I've heard they are all over Plaguewood.", completion = "These will do nicely, {name}. Thank you. Just look at them... so many of them all huddled up. I almost feel bad for the Crusade, but then again, it was never their mill to take, now, was it?", sourceObjectiveStatus = "unverified-source-field" }
quests[5904] = { id = 5904, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plague Upon Thee", description = "Now that we have the termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; find someplace suitable, like on a crate and then open it. The termites should do their work from there and make the mill useless to the Crusade.", sourceObjective = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\n\nProvided item:", completion = "The termites are obviously getting restless as you place the barrel on top of the crate.", sourceObjectiveStatus = "unverified-source-field" }
quests[5921] = { id = 5921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglade", description = "All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.", sourceObjective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", completion = "\"And so it begins, Father Cenarius.  And so it begins.\"\n\nDendrite makes a quick, invisible gesture in the air above him.  A slight aura of power falls over him.\n\n\"The first perspective of nature you must adapt to is that of the bear.  I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5922] = { id = 5922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonglade", description = "All druids are welcomed to the sacred lands of Moonglade, tauren and night elf alike.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.", sourceObjective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", completion = "\"And so it begins, Father Cenarius.  And so it begins.\"\n\nDendrite makes a quick, invisible gesture in the air above him.  A slight aura of power falls over him.\n\n\"The first perspective of nature you must adapt to is that of the bear.  I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5923] = { id = 5923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", sourceObjective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "I'm glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5924] = { id = 5924, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", sourceObjective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "I'm glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5925] = { id = 5925, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", sourceObjective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "I'm glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5926] = { id = 5926, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", sourceObjective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", completion = "I am glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5927] = { id = 5927, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", sourceObjective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", completion = "I am glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5928] = { id = 5928, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heeding the Call", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", sourceObjective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", completion = "I am glad you found your way here today, young {class}.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", sourceObjectiveStatus = "unverified-source-field" }
quests[5929] = { id = 5929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Bear Spirit", description = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches.", sourceObjective = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", progress = "Return only when the Great Bear Spirit has released you back unto me.  Your training cannot continue without its blessing.", completion = "Dendrite makes another invisible gesture in the air above him as you approach.  Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met.  You gaze upon me with strength and knowing intent, though this intent is yet not focused.  You will now learn to focus your strength and adopt the nature of the bear into your work.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5930] = { id = 5930, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Bear Spirit", description = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches.", sourceObjective = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", progress = "Return only when the Great Bear Spirit has released you back unto me.  Your training cannot continue without its blessing.", completion = "Dendrite makes another invisible gesture in the air above him as you approach.  Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met.  You gaze upon me with strength and knowing intent, though this intent is yet not focused.  You will now learn to focus your strength and adopt the nature of the bear into your work.\"", sourceObjectiveStatus = "unverified-source-field" }
quests[5931] = { id = 5931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Darnassus", description = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Mathrengyl Bearwalker walks truly in balance with nature, even as he dwells precariously close to where the balance has faltered.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.", sourceObjective = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.", completion = "Welcome back, {name}.  I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense.  I know it was that way with me.\n\nThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens.  We have come to rely on its wisdom and its power to fuel our purpose.  The time has now come for your first test of this purpose.  Listen closely...", sourceObjectiveStatus = "unverified-source-field" }
quests[5932] = { id = 5932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back to Thunder Bluff", description = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Though the tauren are thought to be young in the ways of Cenarius, Turak Runetotem walks with much balance in the presence of nature.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.", sourceObjective = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.", completion = "Welcome back, {name}.  I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense.  I know it was that way with me.\n\nThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens.  We {race} listen closely to such spirits, and we all prosper from its purpose.  Now, the time has now come for your first test of this purpose.  Listen closely...", sourceObjectiveStatus = "unverified-source-field" }
quests[5941] = { id = 5941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Chromie", description = "You have gathered many relics of the battle of Darrowshire.  Each time you returned with more, my heart yearned for my village... yearned to protect it from its fate.\n\nI know that cannot be, but Chromie, that strange gnome in Andorhal, tells me it is possible.  She says you can save Darrowshire!\n\nShe asked me to gather together the relics, and to have you bring them to her.  She said that she awaits you in the ruined inn of Andorhal.", sourceObjective = "Take the Bundle of Relics to Chromie in Andorhal.", progress = "I have been in contact with your friend Carlin.  He feels great pain for the doom of his village, but he speaks very highly of you and knows that you can set things right.\n\nOh, but I'm drifting from the subject at hand... {name}, do you have the relics I asked for?", completion = "Ah yes, there they are.  Together they weave a powerful spell, one that will raise the spirits of Darrowshire.\n\nWith that spell, and with a little luck, we can save Joseph Redpath!", sourceObjectiveStatus = "unverified-source-field" }
quests[5942] = { id = 5942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Treasures", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you {name}.  Thank you!  You're a very nice <man/lady>!", sourceObjective = "Bring Joseph's Key to Joseph's Chest.", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens...", sourceObjectiveStatus = "unverified-source-field" }
quests[5943] = { id = 5943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gizelton Caravan", description = "You look like a capable {race}. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!\n\nUp ahead is Mannoroc Coven... normally the demons ignore us but something has the kodos spooked this time. I'll pay you to protect the caravan past Mannoroc Coven. Once we are safely past you can receive your reward from our business associate Smeed at Scrabblescrew's Camp.", sourceObjective = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.", completion = "Not sure it's a prosperous proposition to be paying so much money to protect the Gizelton Caravan. Cork and Rigger only make one gold piece a week, but as long as they keep paying for my kodos I can care less how they run their business.", sourceObjectiveStatus = "unverified-source-field" }
quests[5944] = { id = 5944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Dreams", description = "For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become? It has been decades, yet the memories of my father; those precious memories, they are what have kept me alive.\n\nI have dreams, stranger. In these dreams my father is with me. He stands proudly at my side as I am inducted into the Order. We battle legion of Scourge, side by side. We bring honor to the Alliance, to Lordaeron.\n\nI want not to dream anymore.\n\nTake me to him.", sourceObjective = "Escort Taelan Fordring out of Hearthglen.", progress = "<Tirion regains his composure.>", completion = "The death of my son at the hands of these monsters will not pass without incident. Take solace in knowing that the Order is reborn.\n\nI now take my place as Highlord of the new Order of the Silver Hand.\n\nThese possessions of my past - they are all that I have to offer for all that you have done. Please, take these as a symbol of my gratitude; all have served me well over the years.\n\nMay we meet again, in better times, and reminisce of days long past... battles hard fought... dreams redeemed.", sourceObjectiveStatus = "unverified-source-field" }
quests[5961] = { id = 5961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion of the Banshee Queen", description = "It pleases me greatly to see the battle hardened join our cause. Our numbers grow in size and strength as each day passes. Perhaps you are prepared to test your mettle, {class}?\n\nAmong the first of my champions was Nathanos, now known as the Blightcaller. Few exist with more dedication or vigor amidst our ranks.\n\nSeek him out in the Eastern Plaguelands. He resides at the Marris Stead; occasionally roaming the decimated wastes, slaying all Scourge and Alliance filth that cross his path.", sourceObjective = "Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead.", completion = "Surely the Dark Lady does not believe you worthy to meet her champion. You are here to feed my hounds, yes? There could be no other reason for this interruption.", sourceObjectiveStatus = "unverified-source-field" }
quests[5981] = { id = 5981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rampaging Giants", description = "Around 4,000 years ago, Tyrande Whisperwind saved the life of the frostsaber queen, at the hands of rampaging giants. Since then, the frostsabers have been allies of the night elves.\n\nThese same giants that once were a danger to the frostsabers, still exist not too far from here. They are called the frostmaul, and they have taken over the large valley to the south.\n\nProve your loyalty to the frostsabers; kill these giants in the name of the frostsaber queen, Shy-Rotam!", sourceObjective = "Rivern Frostwind wants you to kill 4 Frostmaul Giants and 4 Frostmaul Preservers.", completion = "Excellent, {name}. Your determination has been duly noted.", sourceObjectiveStatus = "unverified-source-field" }
quests[6001] = { id = 6001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body and Heart", description = "Directly east of Auberdine lay many moonkin caves.  The one closest to Auberdine has a Moonkin Stone inside it.  Lunaclaw, the defender of the stone, will face you only when Cenarion Moondust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Moondust, {name}... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!", sourceObjective = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done.", progress = "When you have faced the challenge that lies before you, your understanding of strength of body and strength of heart will be fully realized.  Until that time, I cannot help you further.", completion = "You have finally taken your large step into a much larger world, {name}.  I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.\n\nThere are no further obstacles in your way... let me now teach you what it means to be a {class} of the Claw!", sourceObjectiveStatus = "unverified-source-field" }
quests[6002] = { id = 6002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Body and Heart", description = "On land west of Taurajo in the Barrens - just before it turns into Mulgore - lies a Moonkin Stone.  The moonkin are special beasts, not native to these parts.  Lunaclaw, the stone's defender, will face you when Cenarion Lunardust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Lunardust, {name}... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!", sourceObjective = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done.", progress = "When you have faced the challenge that lies before you, your understanding of strength of body and strength of heart will be fully realized.  Until that time, I cannot help you further.", completion = "You have finally taken your large step into a much larger world, {name}.  I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.\n\nThere are no further obstacles in your way... let me now teach you what it means to be a {class} of the Claw!", sourceObjectiveStatus = "unverified-source-field" }
quests[6004] = { id = 6004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "I was sent as a scout to do some damage and gauge the strength of Hearthglen's defenses. Some people in the Alliance feel the little town has more than historical importance. It's not my job to question what that importance is, but regardless, I'm in no shape to continue until I rest up.\n\nIf you're willing, I'd pay handsomely for some help. Start south of here at their camp near the small bulwark they've set up. If you prove strong enough, maybe I could get your help with my main goal.", sourceObjective = "Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.", progress = "How is it going, {name}? Are they stronger than you thought? I hope not. If I'm going to follow through here, then it's going to require a heck of a lot more strength than what I've already asked you to do.", completion = "Well done, {name}. I'm amazed you dealt with them so quickly. Thank you.\n\nI have yet to meet anyone that approves of the Scarlet Crusade and their methods. I believe in the Light as much as anyone else in Stormwind, but they've demonstrated that they only want to kill anyone not loyal to their movement... even innocents.", sourceObjectiveStatus = "unverified-source-field" }
quests[6021] = { id = 6021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zaeldarr the Outcast", description = "Can you believe that, after all the trouble we have in the plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from the pit below, then take them back to their evil, dead troll hideout--the Undercroft to the west.\n\nGo there and take out Zaeldarr, {name}.  I'm sick to death of his mischief!", sourceObjective = "Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.", progress = "Did you find the hideout, {name}?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!", sourceObjectiveStatus = "unverified-source-field" }
quests[6022] = { id = 6022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Kill With Purpose", description = "You kill with purpose while you remain on my stead.\n\nYour first task is to feed my hounds.\n\nTake this mortar and pestle and travel to Corin's Crossing. Once there, you will find a robust selection of Scourge to slaughter. From their fresh carcasses I need living rot. Take that living rot and grind it up in the mortar, then let it sit to coagulate. Bring the coagulated rot back here.\n\nAnd imbecile, realize that living rot from the undead doesn't remain 'living' for very long. You must kill quickly!", sourceObjective = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", progress = "Are you crying? If this is too 'tedious' for you, 'hero,' I recommend that you head back to the Dark Lady and inform her of the horrible mistreatment you received at my farmstead.\n\nNow get out of my sight!", completion = "Disappointing. I was hoping that I'd be feeding you to my hounds, instead.\n\n<Nathanos sighs.>\n\nWell, at least they'll have something to eat.", sourceObjectiveStatus = "unverified-source-field" }
quests[6023] = { id = 6023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "My real mission was to weaken the Scarlet Crusade's outlying forces and then infiltrate Hearthglen to gauge their numbers. I'm still in no shape to do it on my own, so perhaps I could ask you to aid me again, {name}? From what information I gathered before being discovered, the Crusade has two important members that are the backbone of their forces outside the town: Huntsman Radley and Cavalier Durgen. Kill them, and we're making progress. They should be along Hearthglen Pass outside the town proper.", sourceObjective = "Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.", progress = "Have you found them yet, {name}? With the two of them taken care of, I can proceed to enter Hearthglen to take a closer look at their setup. I can't do it without your help. Please, find Radley and Durgen for me.", completion = "Thank you, {name}. You've been more help than I could have hoped for. The air here just seems to suck my will. I feel tired, and I can tell I'm not getting any better the longer I'm here.\n\nI'm not really sure how I'm going to infiltrate Hearthglen itself and report on how strong the Scarlet Crusade's presence is.\n\nBut that's another matter, before you leave, here, take this... as payment for your help. Thank you again.", sourceObjectiveStatus = "unverified-source-field" }
quests[6024] = { id = 6024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hameya's Plea", description = "Kill me.  Before it's too late.\n\nI am Hameya.  While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed.  We are infected.\n\nI can feel the lich's words now, urging me to reach Zul'Mashar and infect more of my people.  I cannot resist, and so I wrote this scroll before my will left me.\n\nI buried a chest in dirt next to a wagon behind this crypt, but only my key will open it.  I have the key.  If you want my treasure, then find me.\n\nKill me.  Before it's too late.", sourceObjective = "Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", progress = "This chest buried here is securely locked.", completion = "Hameya's chest is opened!!", sourceObjectiveStatus = "unverified-source-field" }
quests[6025] = { id = 6025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unfinished Business", description = "What? Really? You want to know more? But you've already done so much for me, {name}. I couldn't possibly ask you to enter Hearthglen itself on my behalf.\n\nAre you sure, {name}? Hearthglen is much more dangerous than the Pass--I cannot provide you any protection  or even information about what you might face.\n\nWell, if you really are willing to help, then enter the town and find a high place to gain a good view of the town. From there you can gauge their numbers and report them back to me. But be careful....", sourceObjective = "Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.", progress = "It's a dangerous task, {name}. I envy your courage.", completion = "You've done it, {name}! Thank you!\n\nI'll return to Elling... I mean Stormwind as soon as I can. Here, take this coin, it's the least I can do for you. You're a credit to your people, {name}. Thank you and good luck.", sourceObjectiveStatus = "unverified-source-field" }
quests[6026] = { id = 6026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That's Asking A Lot", description = "These here Argent Dawn people commissioned ol' Smokey to do a little demolition work for 'em. Smokey's mammy ain't raised no dummy. When gold coin is slapped on the table, Smokey's services are available. That's my motto!\n\nNow I'd be willing to split the commission with you if you're willing to do a little legwork. Here's the deal: I'm going to head over to Plaguewood and mark the buildings we need destroyed. You gather the components for the bombs. Meet back here when you've got everything. Deal?", sourceObjective = "Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.\n\nYou will have to find a blacksmith and an engineer for these items.", progress = "Trust ol' Smokey, {race}. The reward will be worth it. These Argent Dawn folk don't mess around when it comes to payment.", completion = "I can pay you half up front and half when the job is done.", sourceObjectiveStatus = "unverified-source-field" }
quests[6027] = { id = 6027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book of the Ancients", description = "{name}, I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients. This book contains the secrets of the naga, secrets that have been kept for centuries.  Bring this book to me, and we will learn much about our scaled foes!", sourceObjective = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.", progress = "Ah, {name}!  It's good to see you again.  Do you have the Book of the Ancients?", completion = "The long lost Book of the Ancients!  I will ensure this book is passed on to the high council.  You've done well today, and for that you are to be thanked... as a hero should be thanked!", sourceObjectiveStatus = "unverified-source-field" }
quests[6028] = { id = 6028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Everlook Report", description = "I am looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Pureheart at Chillwind Camp; it's a ways from here, located along the southern fringe of the Western Plaguelands.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from her!", sourceObjective = "Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands.", progress = "Greetings, {class}.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp.  I might also have some work for you...", completion = "Very resourceful, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[6029] = { id = 6029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Everlook Report", description = "I'm looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Garush at the Bulwark; it's a ways from here, located along the western fringe of the Western Plaguelands, east of Tirisfal Glades.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from him!", sourceObjective = "Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands.", progress = "Greetings, {class}.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Bulwark.  I might also offer you the chance to fight for a cause that's worth fighting for!", completion = "Resourceful for a human, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks.", sourceObjectiveStatus = "unverified-source-field" }
quests[6030] = { id = 6030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duke Nicholas Zverenhoff", description = "A recluse medium found in these parts by the name of Umbranse has provided the Argent Dawn with quite a literary masterpiece... one that amounts to quite possibly the largest collection of jibber-jabber I've ever seen written.\n\nOne of the Dawn's most respected leaders, Duke Nicholas Zverenhoff, is a brilliant linguist.  Could you take this to him for me - for a reward, of course?  Light's Hope Chapel - that's where he's currently at, far in the eastern part of the Eastern Plaguelands.", sourceObjective = "Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.", progress = "May the Light guide you in these troubling times, {class}.  What brings you here to this beacon of hope in the middle of darkness and despair?", completion = "This... this is a very special book you have brought me.  I'd like to tell you that \"special\" in this case means \"unique and quite possibly illuminating\", but that remains to be seen.\n\n\"Ooooooo?\"  Who in their right mind thinks this up?\n\nWell now, I've heard of this Umbranse that Gregor spoke of, so this isn't without merit.  I'll do my best to decipher it.  As for you... please, have this - courtesy of the Argent Dawn.  While you are here, perhaps there are some other things you can aid us with.", sourceObjectiveStatus = "unverified-source-field" }
quests[6031] = { id = 6031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Runecloth", description = "In Timbermaw, we are content.  We do not like strangers.  This is good for us, but it is bad for trade.\n\nNot long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak.  runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing.\n\nWill you bring me runecloth?  If you bring me enough, then I will give you something in trade.", sourceObjective = "Bring 30 Runecloth to Meilosh in Timbermaw Hold.", progress = "Do you have the runecloth?  My people are eager for more items of runecloth!", completion = "Ah, you brought the cloth.  Such fine material it is!\n\nThank you, {name}.  You are a true friend.  Please accept this in exchange.", sourceObjectiveStatus = "unverified-source-field" }
quests[6032] = { id = 6032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Cloth", description = "Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us.  But mooncloth is sacred.\n\nBring me a small supply of this holy cloth, and I will teach you a secret fashioning technique.", sourceObjective = "Bring 2 Mooncloth to Meilosh in Timbermaw Hold.", progress = "Have you brought the mooncloth, {name}?", completion = "Ah, very good.  This mooncloth will be used for garments sacred to our people.  Thank you, {name}.  Now I will train you.", sourceObjectiveStatus = "unverified-source-field" }
quests[6041] = { id = 6041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "When Smokey Sings, I Get Violent", description = "While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished.\n\nHere's the plan: I'm going to give you ten sticks of my special compound. You're going to take them over to Plaguewood and plant them inside the Scourge structures that I've had marked for detonation.\n\n<Smokey snaps his fingers.>\n\nBing! It's just that easy.", sourceObjective = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.\n\nOnce you plant the bomb, leave the building and marvel at your handiwork.\n\nBy the way, Smokey's Special Compound is rather... unstable.", progress = "I got supplies left over to make a few more sticks of the special compound. Just let ol' Smokey know if you need more.", completion = "You're much darker than I remember. You got that look going for you; the look that says, 'I've been charred by a high explosive bomb.'\n\n<Smokey laughs.>\n\nAnyhow! Here's your cut of the loot. I've thrown in a little something extra to help soothe the burns.", sourceObjectiveStatus = "unverified-source-field" }
quests[6042] = { id = 6042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Un-Life's Little Annoyances", description = "You cannot take two steps off of this farm without running into one of those obnoxious bats. I want to be able to take the hounds out and slaughter Scourge without being accosted by any damned, dirty bats. Obviously, I have better things to do with my time than mindlessly kill bats day in and day out. You, however, do not.\n\nWhat? Your training? This is your training! Now get out of my sight and don't come back until you've killed a fair number of those winged demons. Don't disappoint me.", sourceObjective = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.", progress = "It could have been worse. I could have had you collecting bat guano.\n\n<Nathanos stares at you in contemplation.>\n\nHrm... Hey! Wait a minute. Where are you going?", completion = "It's incredible what a little anger and rage can get accomplished.", sourceObjectiveStatus = "unverified-source-field" }
quests[6061] = { id = 6061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "As a tauren, it is important to follow the traditions of our ancestors by fighting mighty creatures. By besting these creatures, we are able to intake their spirits, allowing us to become closer to the Earthmother.\n\nIn the same way, taming a beast to fight alongside us helps us become one with nature around us. Eventually, you will learn to tame a beast of your choosing. But all things take practice, and you have much to learn. Begin by taking this taming rod; you must tame an adult plainstrider.", sourceObjective = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", progress = "Practice your skills, {name}. Tame the adult plainstrider.", completion = "Signs have appeared to me from the Earthmother; you have done well.", sourceObjectiveStatus = "unverified-source-field" }
quests[6062] = { id = 6062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "It is an admirable skill to command one's authority over nature. As a hunter, you must strive to learn to use the force and power inherent to any creature of your choosing.\n\nGaining control of an animal is not an easy feat; it is a task that you must undertake with much determination.\n\nFor your first assignment, take this taming rod and use it to tame a dire mottled boar. You can find them quite close to Razor Hill. Practice your skills in battle with the boar at your side, then return to me.", sourceObjective = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.", progress = "Good luck, young {class}.", completion = "You have done well, {name}. I believe you are ready for your next task.", sourceObjectiveStatus = "unverified-source-field" }
quests[6063] = { id = 6063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "As a hunter, it is important to remember the responsibility you hold in your hands. Nature is not a power that can be bent to obey our desires; it is one that is to be respected and acknowledged as something stronger than your very existence.\n\n{name}, you must prove your understanding of this before you will gain the ability to tame an animal to be your companion.\n\nYour first task is to take this taming rod. With it, you will be able to tame a webwood lurker. Tame it, and practice your skills as a hunter.", sourceObjective = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", progress = "You will learn, {name}, and one day you will be a great {class}.", completion = "Excellent, {name}! You are quite a fast learner.", sourceObjectiveStatus = "unverified-source-field" }
quests[6064] = { id = 6064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Hi there, <lad/lass>! So, you'd be wanting to know how you can gain a pet of your own?\n\nWell, let's get started. There's nothing more important than yer equipment when it comes to hunting, but we can chat about my new Shrapnel Blaster some other time. Fer now, let's focus on something I'm sure you're quite interested in: a pet!\n\nThe best way to learn is for you to try out several creatures as companions and see what ya like. So, find a large crag boar, then use the taming rod to tame it.", sourceObjective = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", progress = "Don't worry, lad! You'll get ta try a few before you'll need to decide on just one.", completion = "I know, I know; you're wondering what's next, aren't ya?!", sourceObjectiveStatus = "unverified-source-field" }
quests[6065] = { id = 6065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Yaw Sharpmane at Bloodhoof Village in Mulgore.", completion = "Yes, it is time for you to begin your training.", sourceObjectiveStatus = "unverified-source-field" }
quests[6066] = { id = 6066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Yaw Sharpmane at Bloodhoof Village in Mulgore.", completion = "Yes, I do believe that you are ready...", sourceObjectiveStatus = "unverified-source-field" }
