quests[6068] = { id = 6068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Thotar at Razor Hill in Durotar.", completion = "Yes, I do believe you are ready, as well....", sourceObjectiveStatus = "unverified-source-field" }
quests[6069] = { id = 6069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Thotar at Razor Hill in Durotar.", completion = "Yes, I believe you are ready to be trained...", sourceObjectiveStatus = "unverified-source-field" }
