quests[6073] = { id = 6073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Dazalar at Dolanaar in Teldrassil.", completion = "Yes, it is time to train you...", sourceObjectiveStatus = "unverified-source-field" }
quests[6074] = { id = 6074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Grif Wildheart at Kharanos in Dun Morogh.", completion = "Yes, I believe that it is time...", sourceObjectiveStatus = "unverified-source-field" }
quests[6075] = { id = 6075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Grif Wildheart at Kharanos in Dun Morogh.", completion = "Yes, I believe that it is time for you to be trained...", sourceObjectiveStatus = "unverified-source-field" }
quests[6076] = { id = 6076, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hunter's Path", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", sourceObjective = "Speak with Grif Wildheart at Kharanos in Dun Morogh.", completion = "Yes, {class}, it is time...", sourceObjectiveStatus = "unverified-source-field" }
quests[6081] = { id = 6081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Orgrimmar. There you must speak to one of our most revered hunters, Ormak Grimshot. He will give you the ability to train your new pet. You will find him in the Valley of Honor.\n\nGood luck, {name}.", sourceObjective = "Speak with Ormak Grimshot in Orgrimmar.", completion = "A young {class}, I see. Yes, I will grant you the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nNow, go, {class}. We will speak again, at a later date.", sourceObjectiveStatus = "unverified-source-field" }
quests[6082] = { id = 6082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The final creature you need to tame is one you should strive to emulate; the armored scorpid. It strikes quickly and confidently; to control a force such as this is your fate as a hunter.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing; this creature will be yours to command. Under your control, your pet will gain experience alongside you. I will also show you how to call it and dismiss it as you wish.", sourceObjective = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill.", progress = "Were you able to tame the scorpid?", completion = "You have learned all I can teach you, {name}. It is time for you to take what you have learned here and choose a pet of your own.\n\nHere you are, {name}. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them.", sourceObjectiveStatus = "unverified-source-field" }
quests[6083] = { id = 6083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The advantage a pet affords you against your rivals is duly noted, {name}. When you gain control over another creature, you are adding to your own strength. Your pet must become an extension of yourself.\n\nThe next task requires you to turn from the land; you will find the next creature in the waters off the coast. Across from Sen'jin Village, near the Echo Isles. look for a spirited crab called the surf crawler. Use the taming rod to tame it, then practice your skills.", sourceObjective = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.", progress = "You need to practice in order to gain the skills you need to effectively control your pet. Have you tamed a surf crawler?", completion = "You are a swift learner, {name}. You have done well.", sourceObjectiveStatus = "unverified-source-field" }
quests[6084] = { id = 6084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Those crag boars are quite burly; maybe you'd like something with a little more finesse? Alright then, I've got jus' the thing. South and east of here, you'll find large white cats called snow leopards. Just like an elegantly-carved rifle, behind their beautiful exterior lies a powerful fighter, capable of doing extreme damage. You'll find them to be much more agile an' swift than the boar you tamed.\n\nTake this taming rod and see how you like the snow leopard.", sourceObjective = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.", progress = "What do you think of the snow leopard, {name}?", completion = "When I feel you've learned enough, I will grant you the ability to choose any pet of your liking.", sourceObjectiveStatus = "unverified-source-field" }
quests[6085] = { id = 6085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "Perhaps you'd like a creature that possesses little more than brute strength. The ice claw bear is an excellent companion for a fledgling hunter like yourself, and can be found east of Kharanos. Here is the taming rod; try this animal as a pet and see if ya like it!\n\nWhen you return, I'll give ya the skills you will need to tame an animal of your choosing; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as ya like.", sourceObjective = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", progress = "Have you tamed the ice claw bear yet?", completion = "Here you are, {name}. I will now give ya the power to tame a beast, as well as call it and dismiss it as you please.\n\nFind yerself a good, loyal pet, and enjoy the hunt!", sourceObjectiveStatus = "unverified-source-field" }
quests[6086] = { id = 6086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training the Beast", description = "{name}, ya now have the power to tame a pet, but you must also gain the skills ta train it.\n\nTravel to Ironforge and find the Hall of Arms. There you must speak to one of our most revered animal trainers, Belia Thundergranite. She'll give ya the power to train your new pet, so get goin', <lad/lass>!\n\nBelia is a friendly sort; you should have no problems gaining her approval. Good luck, {name}.", sourceObjective = "Speak with Belia Thundergranite in Ironforge.", completion = "A new recruit, eh? You're on your way to becoming a great {class}, I see.\n\nYes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember that the key to getting the most from your new pet is to respect it and treat it well. In turn, your pet will be your most loyal friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[6087] = { id = 6087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have a fiery spirit, hunter, readily awaiting your next challenge.\n\nYour next task is to gain the companionship of a wolf known as the prairie stalker. This creature is swift and fearless; in taking this beast as your pet, you must also take on these qualities.\n\nDuring a battle, you will learn how you and your pet will become a team. In the end you must work as one, muscle to muscle.\n\nHere is the taming rod, {name}. Tame a prairie stalker and practice your skills.", sourceObjective = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", progress = "Have you found a prairie stalker?", completion = "Yes... The Earthmother believes that you are ready for the next lesson.", sourceObjectiveStatus = "unverified-source-field" }
quests[6088] = { id = 6088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The final task that I have for you requires that you tame a creature that inhabits the sky. The swoop is a difficult opponent, but as your ally, you will acquire its sharp attacks and threatening presence.\n\nBy the will of the Earthmother, when you return I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.", sourceObjective = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", progress = "You will soon be ready, {name}.", completion = "You have learned all I can teach you, {name}. May the blessings of the Earthmother guide you in choosing a pet.\n\nHere you are, {name}. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride and honor the Earthmother.", sourceObjectiveStatus = "unverified-source-field" }
quests[6089] = { id = 6089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Thunder Bluff. There you must speak to one of our most revered hunters, Holt Thunderhorn. If he deems you worthy, he will give you the ability to train your new pet.\n\nHolt has bested the most powerful and feared beasts of Azeroth, and commands many strong creatures of his own. His ties to the Earthmother are strong, and you can learn much from him. Good luck, {name}.", sourceObjective = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff.", completion = "A young {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nNow, go forth. May the Earthmother guide you on your path. We shall speak again, at a later date.", sourceObjectiveStatus = "unverified-source-field" }
quests[6101] = { id = 6101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "The variance of nature is something that can be relied upon, {name}. It is predictable in the way that it never remains the same; it is always changing.\n\nThe tasks I give to you will help you to see and appreciate the vast differences of the creatures you may choose as your companion.\n\nTake this taming rod and use it to tame a nightsaber stalker, found to the south. Practice your skills as a hunter. Then you will begin to understand the similarities and differences of nature.", sourceObjective = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", progress = "Understanding the balance between nature and oneself is a way of life for every {race}.", completion = "I see your commitment and that you have understood what I have taught you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6102] = { id = 6102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taming the Beast", description = "You have tamed two creatures that inhabit the land, now you must tame one that soars the skies. Use the taming rod to tame a strigid screecher, found west of here. Practice your skills with this mighty owl at your side.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.", sourceObjective = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", progress = "I am proud of your accomplishments, {name}. Have you finished the last task I gave you?", completion = "You have learned all I can teach you, {name}. May I offer you one more piece of advice: use discretion when choosing your first pet. Will you choose a creature of the land, of the water, or of the sky? Whatever it may be, without doubt, your pet will be with you for quite some time.\n\nHere you are, {name}. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them.", sourceObjectiveStatus = "unverified-source-field" }
quests[6103] = { id = 6103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training the Beast", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Darnassus. There you must speak to one of our most revered hunters, Jocaste. She will give you the ability to train your new pet, so make haste.\n\nWhile Jocaste may seem stern, she is always pleased to see another hunter rising through the ranks. Treat her with respect and she will return in kind. Good luck, {name}.", sourceObjective = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.", completion = "A fledgling {class}, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, {name}, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date.", sourceObjectiveStatus = "unverified-source-field" }
quests[6121] = { id = 6121, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons Anew", description = "You're now ready to learn about poison and the power we as druids have over it, {name}.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.", sourceObjective = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.", completion = "Greetings young {class}, I'm glad to see you ready and eager to learn about the curing of poisons.\n\nWhile most druids in the past were put through pre-planned trials, your work will involve no such thing.  There has been a rash of animal poisonings in Auberdine, and the village there has been unable to cure it.  To that end, a representative there has asked Moonglade for aid and we are sending you there to aid them.  This is no exercise - the work you'll do is quite real.  Bear this in mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[6122] = { id = 6122, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Principal Source", description = "The Cliffspring Falls in Darkshore serves as the principal source of drinking water for the region, and now I suspect it is the principal source of the poison that is harming the local fauna - deer specifically.  Use this sampler to draw some water from the mouth of the cave; be careful, as dangerous naga now reside in a cave by the falls.\n\nOnce filled, deliver it to Alanndarian Nightsong in Auberdine.  She is the one that requested our aid, and you will work with her to address this malady.", sourceObjective = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.", progress = "You're the one that the Cenarion Circle in Moonglade sent?  That's wonderful!  We've quite the crisis our hands here regarding the poor deer, and we're happy for all the help we can get.\n\nDo you have the sample of water that Dendrite Starblaze said you'd have?  He notified me that you'd draw one so we could work on a cure together...", completion = "By Elune, this water is disgusting!  No wonder the deer are sick.\n\nSomething is polluting the water, and in turn corrupting Darkshore's entire water table.  Sick deer have been seen all over area, and not just by the river.  While this water is most likely a primary source of the sickness spreading, there's something else at work here.\n\nThis water, believe it or not, will help us formulate a cure.  While I research this water, I have need of some items to formulate a cure...", sourceObjectiveStatus = "unverified-source-field" }
quests[6123] = { id = 6123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Cure", description = "The water will serve as the base of the curative salve I'll make for the deer.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if we're unlucky and you aren't one then you'll need to find one to help us out.\n\nFinally for potency, I need some lunar fungus.  Finding lunar fungal blooms is easy enough; they're all over the place in caves just to the east of here.  Moonkin reside in the caves and they're irritable as of late, so be careful.", sourceObjective = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.", progress = "Have you got the reagents I need to make the salve?  The deer aren't getting any better on their own, so we better hurry to help them out!", completion = "This is good, {name}, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.\n\nMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it.  Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!\n\nNow, let me get to work on this!", sourceObjectiveStatus = "unverified-source-field" }
quests[6124] = { id = 6124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curing the Sick", description = "The amount of salve made out of the reagents you brought me is good enough for ten doses, {name}.  While I work with the village to try and make some more salve, I'd like for you to help us get a head start.  All around Darkshore are sickly deer; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend Auberdine's thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!", sourceObjective = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.", completion = "You have done well in tending to the sickly deer of Darkshore; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  There are those in Darnassus who choose to recognize this threat... and there are those who ignore the growing signs.  I hope you will not be one to put blinders on about what facts stare you in the face, {name}.\n\nRegardless, you've proven your worth as a friend of nature and the Circle - take this as a symbol of such.", sourceObjectiveStatus = "unverified-source-field" }
quests[6125] = { id = 6125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power over Poison", description = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Mathrengyl Bearwalker in Darnassus, {name}.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid.  We shall speak again.", sourceObjective = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", completion = "Welcome back - I've been following your progress on this lesson since you left, and I must admit I was surprised to learn about the situation in Auberdine.  This does bear some further investigation, as the introduction of such poisons into the environment is most upsetting to the balance.\n\nYou handled yourself with grace under pressure.  For that, I can find no better way to reward you than with permanent power over poison.  Use it well, {name}... use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[6126] = { id = 6126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons Anew", description = "You're now ready to learn about poison and the power we as druids have over it, {name}.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.", sourceObjective = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.", completion = "Greetings young {class}, I'm glad to see you ready and eager to learn about the curing of poisons.\n\nWhile most druids in the past were put through pre-planned trials, your work will involve no such thing.  There has been a rash of animal poisonings at the Crossroads in the Barrens, and they're unable to bring it under control.  Someone there has requested Moonglade for aid, so we are sending you there to aid them.  This is no exercise - the work you'll do is quite real.  Bear this in mind.", sourceObjectiveStatus = "unverified-source-field" }
quests[6127] = { id = 6127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Principal Source", description = "Dreadmist Peak to the northwest of the Crossroads is most likely a primary candidate as to the source of the spread of the poison.  Its airy peaks have pools of water that influence the weather patterns.  I suspect the water is now tainted by the demon-worshipping Burning Blade.\n\nUse this sampler to draw water from the pool at the very top of the peak.  Once filled, deliver it to Tonga Runetotem at the Crossroads.  He is the one that requested our aid, and you will work with him to address this malady.", sourceObjective = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens.", progress = "You are the one that the Cenarion Circle in Moonglade sent, yes?  This is most fortuitous for us!  We are stymied in our effort to bring balance to the sickly gazelles that wander the northern Barrens; we're happy for all the help we can get.\n\nDo you have the sample of water that Dendrite Starblaze said you'd have?  He notified me that you'd draw one so we could work on a cure together...", completion = "By my ancestors, this water is disgusting!  No wonder the gazelles are sick.\n\nSomething is polluting the water, and in turn beginning to wreck the northern Barrens ecosystem.  Sick gazelles have been sighted all north of the east-west road here.  While this water is most likely a primary source of the sickness spreading, there's something else at work here.\n\nThis water, believe it or not, will help us formulate a cure.  While I research this water, I have need of some items to formulate a cure...", sourceObjectiveStatus = "unverified-source-field" }
quests[6128] = { id = 6128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Cure", description = "The water will serve as the base of the curative salve I shall make for the gazelles.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if you are not familiar with this skill you'll need to find one to help us out.\n\nFinally for potency, I need kodo horns - mere chips and fragments will not suffice.  Kodos you can handle wander the northern part of the Barrens; bring some down for the greater good of the balance {name}, and fetch the horns for me.", sourceObjective = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.", progress = "Have you got the reagents I need to make the salve?  The gazelle aren't getting any better on their own, so we better not tarry in our effort to save them!", completion = "This is good, {name}, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.\n\nMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it.  Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!\n\nNow, let me get to work on this!", sourceObjectiveStatus = "unverified-source-field" }
quests[6129] = { id = 6129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curing the Sick", description = "I was able to make enough salve for ten doses of curing, {name}.  While I work with local authorities to try and make some more salve, I'd like for you to help us get a head start.  All around the northern Barrens are sickly gazelles; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend our thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!", sourceObjective = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.", completion = "You have done well in tending to the sickly gazelles of the Barrens; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  You {race} are most eager to understand the ways of Cenarius; you, like your elders in Thunder Bluff, are proving that the need for balance transcends artificial racial barriers.\n\n{name}, you've proven your worth as an friend of nature and the Circle - take this as a symbol of such.", sourceObjectiveStatus = "unverified-source-field" }
quests[6130] = { id = 6130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power over Poison", description = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Turak Runetotem in Thunder Bluff, {name}.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid.  We shall speak again.", sourceObjective = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff.", completion = "Welcome back - I've been following your progress on this lesson since you left, and I must admit I was surprised to learn about the situation at the Crossroads.  This does bear some further investigation, as the introduction of such poisons into the environment is most upsetting to the balance.\n\nYou handled yourself with grace under pressure.  For that, I can find no better way to reward you than with permanent power over poison.  Use it well, {name}... use it well.", sourceObjectiveStatus = "unverified-source-field" }
quests[6131] = { id = 6131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timbermaw Ally", description = "The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.\n\nAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.", sourceObjective = "Grazle wants you to prove yourself by killing 5 Deadwood Warriors, 5 Deadwood Pathfinders, and 5 Deadwood Gardeners.", sourceObjectiveStatus = "unverified-source-field" }
quests[6132] = { id = 6132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Me Out of Here!", description = "Get me out of here!\n\nI came up to the Valley of Spears to talk to the Maraudines.  I thought I could do a little business with them... but they don't want to talk!  I think they want to eat me!\n\nGet me out of here and my brother Hornizz will pay you big!  He's at our camp next to the kodo graveyard, to the east.\n\nLet's hurry, {name}.  Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...", sourceObjective = "Escort Melizza Brimbuzzle.", progress = "Have you seen my sister Melizza?  She's always on the go, which gets her into trouble all the time.", completion = "My sister Melizza said you'd be coming.  Thanks a lot for getting her out of the jam she was in; it's too bad that she's already probably found herself in a new one!", sourceObjectiveStatus = "unverified-source-field" }
quests[6133] = { id = 6133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ranger Lord's Behest", description = "The high elves of the Quel'Lithien lodge possesses something that belongs to me, {class}: A document detailing my life as a mortal.\n\nBefore you ask; no, you most certainly are not privy to such information. Just do as I tell you, worm: Recover the registry.\n\nAnd imbecile, be sure to leave as much strife and grief as possible in your wake. Leave them suffering...", sourceObjective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.\n\nYou must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", progress = "Do not leave me waiting, {class}.", completion = "I trust you did not read the registry. Not even you would do something that idiotic...", sourceObjectiveStatus = "unverified-source-field" }
quests[6134] = { id = 6134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghost-o-plasm Round Up", description = "There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts.  Sounds scary, doesn't it?  Well think how scary it is to the Magram!  If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs.\n\nHere, take this crate of ghost magnets.  If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it.  Distance yourself, take out the ghosts and get their ghost-o-plasm--that's what we'll sell to the Magram.", sourceObjective = "Collect 8 Ghost-o-plasms.", progress = "Where's my ghost-o-plasm, {name}?", completion = "There it is!  Looks like you got some of it on you too.  Kinda slimey, eh?\n\nWell, thanks a lot for all the trouble, {name}.  This stuff will be worth a fortune... if I can convince the centaurs what it is!", sourceObjectiveStatus = "unverified-source-field" }
quests[6135] = { id = 6135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Duskwing, Oh How I Hate Thee...", description = "Up until now, you have completed the missions I have assigned; even if not in the most timely manner.\n\nI suppose you think that you are ready for a challenge. Yes... Yes, imbecile, perhaps you are ready for a more involved set of missions.\n\nThe albino demon bat, Duskwing, roams the countryside just north of here. Track him down and destroy him. Return to me with a patch of his white fur and you shall be rewarded.", sourceObjective = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.\n\nIt is said that Duskwing roams the countryside to the north of Marris Stead.", progress = "I would not recommend that you take on this challenge alone, {class}.", completion = "Excellent work, imbecile. I shall fashion this fur into something you can use.", sourceObjectiveStatus = "unverified-source-field" }
quests[6136] = { id = 6136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Corpulent One", description = "Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor. Borelgore has been known to devour others who tried to hunt him.", sourceObjective = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.", progress = "Have I told you lately that I hate you?", completion = "Keep this up and I may have to promote you from imbecile to mental deficient, first class.", sourceObjectiveStatus = "unverified-source-field" }
quests[6141] = { id = 6141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brother Anton", description = "My brother in arms, Brother Anton, heard rumors of an undead infestation in distant Kalimdor, in a land known as Desolace.  Anton immediately booked passage to that place, to seek and destroy the undead menace!\n\nHe is looking for those with the bravery and resolve to aid him.  If your heart is true, then speak with Anton.  He is in Desolace, in the Alliance town of Nijel's Point.", sourceObjective = "Speak with Brother Anton in Desolace.", completion = "I received word of aid arriving from the east.  Are you the source of these rumors?  Have you come here to help the Scarlet Brother in its crusade?\n\nIf so, then listen close...", sourceObjectiveStatus = "unverified-source-field" }
quests[6142] = { id = 6142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clam Bait", description = "You have the look of a fisherman, {class}! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?\n\nUp north you will find a wrecked ship off the coast. Soft-shelled clams are littered throughout the area. If you bring me back 10 pieces of soft-shelled clam meat, I will give you something in return.", sourceObjective = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.", progress = "I can't wait to go fishing with some fresh soft-shelled clam meat; did you bring me the 10 pieces of it I need?", completion = "Perfect mon, this is just what the witch doctor told me to do for my headache. He says, \"Mai'Lahii - go fish. It'll make you feel better\"\n\nWell, I feel better already, thanks mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[6143] = { id = 6143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Other Fish to Fry", description = "Maybe you heard or maybe you haven't... my crew and I was out fishing near Ranazjar Isle, north of the wrecked ship off the coast up north. We used to fish there all the time; now all I do is think of a way to seek revenge for my fallen comrades.\n\nThe naga attacked us one morning, killing everyone except me.\n\nMe conscience can't handle the guilt, {class}; I need you to go and fry them naga for me. I'll make the effort worth your while; you think you can help me with that?", sourceObjective = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.", completion = "As sweet as it is hearing the news that the naga have been vanquished, my heart still feels empty. For the rest of my life I will be dedicated to having them all killed.\n\nHere mon, your reward as I promised. It's small in comparison to the gratification of knowing the naga fried for their hated act upon my crew.", sourceObjectiveStatus = "unverified-source-field" }
quests[6144] = { id = 6144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call to Command", description = "The order has come down, {class}. Bragor Bloodfist himself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to Bragor Bloodfist. Do not embarrass me, {class}!", sourceObjective = "Travel to the Undercity and speak with Bragor Bloodfist.", completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into your lands, desecrate your structures and monuments and murder your people.\n\nThe Dark Lady has commanded that I deal with this insect once and for all. You will become the instrument of the Forsaken's reckoning.", sourceObjectiveStatus = "unverified-source-field" }
quests[6145] = { id = 6145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Crimson Courier", description = "Just as the body cannot survive without the head, the head cannot survive without the body. The defenses of the Scarlet Crusade's command inside Stratholme are almost impenetrable. We must, instead, cut the body out from under the head.\n\nMy Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, {race}! Find the Crimson Courier and recover that report. Return it to Nathanos.", sourceObjective = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.", progress = "Succeed now and you will have almost earned my respect, {class}.", completion = "<Nathanos laughs.>\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!", sourceObjectiveStatus = "unverified-source-field" }
quests[6146] = { id = 6146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nathanos' Ruse", description = "I have made some adjustments to this command. Should our little ruse work, they will expose the Scarlet Oracle and we shall strike!\n\nNow pay attention, {class}. You are to deliver this command to the Crusader Lord, Valdelmar.\n\nHow? You are going to hand it to him, imbecile.\n\nTake the command and this rotten apple to Tyr's Hand. When you cross into the city, eat the apple. You will transform into something more... palatable to the humans. Take the command and hand it to the Crusader Lord, Valdelmar.", sourceObjective = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar.", progress = "This is unacceptable, soldier!", completion = "Where have you been? We had thought the Scourge had captured you.", sourceObjectiveStatus = "unverified-source-field" }
quests[6147] = { id = 6147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Nathanos", description = "The Grand Crusader makes an unusual request. Hrm, regardless... what he asks will be done. Return to the Scarlet Bastion and notify him that the Oracle will be en route shortly.\n\nWe will take every precaution to ensure that she makes it to Stratholme unharmed.", sourceObjective = "Return to Nathanos Blightcaller with the new information.", completion = "The fools! My deception went unnoticed! Prepare yourself, {class}. We must strike with cold cunning!", sourceObjectiveStatus = "unverified-source-field" }
quests[6148] = { id = 6148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Scarlet Oracle, Demetria", description = "Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge.\n\nWhile this ruse was successful in exposing her, if she truly does possess psychic powers, she will undoubtedly be expecting some sort of trouble. You are going to provide that 'trouble.'\n\nTrack down the Oracle and terminate her. They should be moving out of Tyr's Hand as we speak. Make me proud, worm.", sourceObjective = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.", progress = "What is your status, {name}?", completion = "They will be reeling from this blow for years! Well done, {name}! You have earned not only my respect but also this reward.", sourceObjectiveStatus = "unverified-source-field" }
quests[6161] = { id = 6161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claim Rackmore's Treasure!", description = "Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures.  To prevent his treasure from falling into enemy hands, he hid his chest on Ranazjar Isle.\n\nTo open the chest requires two keys, a silver and a gold.  These keys were lost, but if the keys and the chest are found, a treasure awaits!", sourceObjective = "Find Rackmore's Silver Key. Find Rackmore's Golden Key. Find and open Rackmore's Chest.", progress = "This chest is securely locked.", completion = "Chest opens to reveal Rackmore's treasure!", sourceObjectiveStatus = "unverified-source-field" }
quests[6162] = { id = 6162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Husband's Last Battle", description = "My husband traveled Felwood for the honor of our clan, doing battle against the Shadow Council and other corrupt atrocities!\n\nAfter he escaped death numerous times, I received a letter from him saying that a druid asked him for help against a great befouled furbolg named Overlord Ror--the two were never heard from again.\n\nI want this Ror's clawed hand, {name}. I want it to pay for leaving me a widow! I believe the creature is to the south... near the Ashenvale border.", sourceObjective = "Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.", progress = "Do you have the beast's claw yet, {name}? It will pay for its crimes. I don't care if it's corrupt or just angry for living in such a dismal forest. No furbolg will live for long committing such crimes against my family!", completion = "You bring honor to me for following through with your word. My husband died in battle--he would have been proud of that. But I could not rest until I knew that the creature that has forced me to live my life alone paid for what it had done.\n\nThank you again, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6163] = { id = 6163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ramstein", description = "I was overwhelmed. On this very stead, I stood... held my ground in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge.\n\nThe wretch. The filth. It hovered above me, entrails hanging from its gaping chest cavity.\n\nI woke as Scourge. For so long I was helpless. My mind had coalesced with the Lich King's.\n\nShe came for me... somewhere, somehow, I knew she would. Free.\n\nAnd now, I must have my vengeance - my vengeance on that which took from me my life. Destroy it.", sourceObjective = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.", progress = "After Sylvanas freed me, I hunted the beast across these wastes for months. It fled to the safety of Stratholme. The bastard...", completion = "I wonder... did it beg for mercy? Could it know what mercy is?\n\n<Nathanos spits.>\n\nI will hang this beast's head upon my wall.\n\nYou have earned a spot amongst one of my champions, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[6164] = { id = 6164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Augustus' Receipt Book", description = "I'm ready for business!  What you do want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", sourceObjective = "Get Augustus' Receipt Book from the inn in Terrordale.", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, {name}!  Stupendous!  Insanely good, I say!", sourceObjectiveStatus = "unverified-source-field" }
quests[6181] = { id = 6181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Message", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Thor, our gryphon master.  He's just down the hill; bring him my note, and then take a gryphon to Stormwind.", sourceObjective = "Bring Lewis' Note to Thor the gryphon master.", progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!", sourceObjectiveStatus = "unverified-source-field" }
quests[6182] = { id = 6182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The First and the Last", description = "Nathanos Marris was the first and last of the human ranger lords. A disciple of Sylvanas Windrunner, now the Banshee Queen of the Forsaken.\n\nWe had thought that Nathanos had been killed in action in the defense of Lordaeron five years ago. Although his corpse was never recovered, it was assumed that he did not make it out of the Eastern Plaguelands.\n\nMathias Shaw has been investigating the disappearance and may have some new information. Report to him at once. He resides in Old Town, at the Barracks.", sourceObjective = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.", completion = "After some reports of unusual Forsaken activity in the Eastern Plaguelands, SI:7 agents were dispatched to investigate. The results of that investigation are unsettling.", sourceObjectiveStatus = "unverified-source-field" }
quests[6183] = { id = 6183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Dead", description = "Five of my best field agents were assigned the Marris case. One returned, only to end up dead in his sleep three days later.\n\nWhat little information we did manage to get out of him was incoherent gibberish. We made out two words: \"Nathanos,\" and \"Blightcaller.\"\n\nI do not have the available manpower to continue this investigation and Ravenholdt will not assist us. We must get to the bottom of this; if only to provide closure to the families of the deceased. Will you help?", sourceObjective = "Speak with Mathias Shaw again if you wish to accept his task.", completion = "<Mathias nods.>\n\nI had faith that Bolvar would send me men and women of honor - the most dedicated soldiers of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[6184] = { id = 6184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flint Shadowmore", description = "The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.\n\nFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.\n\nGood luck, {name}.", sourceObjective = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore.", completion = "The first mission will be straight up, {name}. You go in, you come out. Recon...", sourceObjectiveStatus = "unverified-source-field" }
quests[6185] = { id = 6185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Eastern Plagues", description = "As I said, your first mission is one of reconnaissance. Nothing fancy, {name}. You must travel to the Eastern Plaguelands and look for any clues as to this Blightcaller.\n\nBe on the lookout for information about our missing operatives. We have to assume that they are dead and if they are dead, they must have a corpse... somewhere.\n\n<Flint swallows hard.>\n\nAll SI:7 agents carry this insignia.\n\n<Flint shows you his SI:7 insignia.>\n\nBring any of those that you may find back to me.", sourceObjective = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", progress = "An... Any luck??", completion = "Rutger. Fredo. Turyen. All... dead...\n\n<Flint clutches the insignias tightly.>\n\nWhere were they? Did you discover any more information about this bastard, the Blightcaller?", sourceObjectiveStatus = "unverified-source-field" }
quests[6186] = { id = 6186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blightcaller Cometh", description = "<The blood appears to have completely drained from Flint's face.>\n\nNa... Nathanos did this? Nathanos is the Blightcaller?\n\nWhy? He was... was so noble - a ranger lord respected by all. The only human ever allowed to train under the high elves. Now a ruthless agent of the Forsaken?\n\nI... I am sorry to ask this of you, {name}, but King Wrynn must be informed of this turn of events at once. Please, return to Stormwind and deliver the news.", sourceObjective = "Return to Stormwind and inform King Varian Wrynn of the fate of Nathanos Marris.", completion = "No. It... NO! How? An agent of the Forsaken? The CHAMPION of the Banshee Queen???\n\n<Highlord Bolvar Fordragon slumps in defeat.>", sourceObjectiveStatus = "unverified-source-field" }
quests[6187] = { id = 6187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Order Must Be Restored", description = "Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?\n\nNathanos' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.\n\nAnd now... the champion of the Forsaken.\n\nNo. This cannot be. Order must be restored.\n\nGather an army, {name}. Return to the Plagues with your army and destroy the Blightcaller.\n\nI wish you luck, {name}. Truly, you will need it for this battle.", sourceObjective = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.\n\nKeep your wits about you, {name}. The Horde will defend the ranger lord with their very lives.", progress = "<Highlord Bolvar Fordragon is lost in thought.>", completion = "It is a tragedy. I think... I believe that our kind is cursed, {name}. We are cursed to lose our greatest warriors; our most noble heroes; our most gifted scholars.\n\nWe are indebted to you and I assure you, {name}, wherever Nathanos Marris is now, he smiles down upon you.", sourceObjectiveStatus = "unverified-source-field" }
quests[6221] = { id = 6221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deadwood of the North", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  For this reason, I am deeply saddened by having to fight my own brethren.\n\nPlease, {name}, do what must be done, and do not mention the details; they upset me far too much.", sourceObjective = "Nafien would like you to kill 5 Deadwood Den Watchers, 5 Deadwood Avengers, and 5 Deadwood Shamans.", sourceObjectiveStatus = "unverified-source-field" }
quests[6241] = { id = 6241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterfall Activity", description = "The Timbermaw tend to stay to themselves, {name}. While we do allow safe passage to those that have proven they can be trusted, we try to avoid other furbolg tribes if at all possible.\n\nLately I have noticed that the Winterfall tribe has become increasingly hostile towards us. They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nIf you could reduce their numbers this would help us greatly, {name}.", sourceObjective = "Salfa wants you to kill 6 Winterfall Totemics, 6 Winterfall Den Watchers, and 6 Winterfall Pathfinders.", sourceObjectiveStatus = "unverified-source-field" }
quests[6261] = { id = 6261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dungar Longdrink", description = "{name}, I gathered into this crate everything Lewis asked for.  Can you take it to him?\n\nIf you've already spoken to Thor in Westfall, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Lewis as fast as you can.  We don't want our fighting men and women in Westfall to go without fresh equipment!", sourceObjective = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Westfall, eh?  Have you been to Westfall before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!", sourceObjectiveStatus = "unverified-source-field" }
quests[6281] = { id = 6281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Continue to Stormwind", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Lewis' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", sourceObjective = "Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Quartermaster Lewis?  I'm not surprised he needs more gear.  Sentinel Hill is far away, in a land Stormwind has all but forgotten.\n\nWell thank you, {name}.  Here's some money to cover your travel costs.", sourceObjectiveStatus = "unverified-source-field" }
quests[6282] = { id = 6282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harpies Threaten", description = "Tauren take pride as the protector of these lands. Undoubtedly you can guess why I am alarmed with the number of harpies that dwell here in Stonetalon.\n\nThe Bloodfuries are the source of the increasing number of harpies in Kalimdor; they encroach upon all likes of life preventing the innocent from leaving their boundaries.\n\nI need you to cull the harpies, {name}!", sourceObjective = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", progress = "Do not be weary of Charred Vale; many evil creatures reside in those hills. Stay strong {name}, and you shall prevail over this threat to our people. Go now and strike hard - our children shall never know of the evil of what was.", completion = "This is most excellent news! Tell me again how you cast fear into the cold hearts of those vile harpies. The Bloodfuries have been dealt a serious blow!", sourceObjectiveStatus = "unverified-source-field" }
quests[6283] = { id = 6283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloodfury Bloodline", description = "Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!\n\nShe is all but a queen to those filthy creatures. Slay her and their numbers will surely diminish.\n\nGo back into the Charred Vale and you will find her along the western hills. She will not be easy to vanquish, but the reward will be great.", sourceObjective = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.", progress = "Bloodfury Ripper is a nasty creature! You will have success finding her along the western hill line in the Charred Vale.\n\nThe bloodfuries will be helpless with out... surely we can vanquish them forever!", completion = "Already I feel the anger leave me. What will I do with my time? Knowing evil moves near my land kept my thoughts moving, though now they are silent. Perhaps this is a good thing... maybe now I can focus on the good, as all Tauren should.\n\nPlease accept this as a reward for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[6284] = { id = 6284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arachnophobia", description = "Warning: Proceed into Sishir Canyon west of here at your own risk.\n\nBesseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair.\n\nMaggran Earthbinder in Sun Rock Retreat has placed a bounty on Besseleth. Slay her and bring proof of your killing to Maggran; there you will receive your reward for disposing this eight-legged menace.", sourceObjective = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.", progress = "Besseleth is a ruthless predator... I fear for those that travel Webwinder Path at night. It's then that she and her children prey upon innocent travelers. I myself fell prey to her two-foot fang of death, but luckily I was able to fend her off and get to safety. I would give anything to see that monster destroyed.", completion = "Good hunting, {name}! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.\n\n\n\nPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark.", sourceObjectiveStatus = "unverified-source-field" }
quests[6285] = { id = 6285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Lewis", description = "The gryphon master in Westfall is Thor.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Thor, so just speak with me again when you're ready to take a gryphon to Westfall.  Once there, you can deliver Osric's Crate to Quartermaster Lewis.", sourceObjective = "Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill.", progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, {name}.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Sentinel Hill often!", sourceObjectiveStatus = "unverified-source-field" }
quests[6301] = { id = 6301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cycle of Rebirth", description = "Industrial greed and continuous war have wrecked the lands of Stonetalon. Only the blessings of the Earthmother can cure such injury.\n\n{name}, I will require you to seek a special seed, the Gaea seed. They are only found here in Stonetalon Mountain, north of Sun Rock Retreat at Mirkfallon Lake, near the water's edge.\n\nOnce you bring me the seeds I will imbue them with shamanistic power to speed their growth.", sourceObjective = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.", progress = "The continuous destruction caused by war and those that seek a profit from lumber pains me deeply. To aid the cycle of rebirth and replenish the lands, I need Gaea seeds. Do you have them, {class}?", completion = "Ah, {name}, you have the Gaea seeds. Watch and see how the blessing of the Earthmother can cause even these small kernels of life to bloom and flourish.", sourceObjectiveStatus = "unverified-source-field" }
quests[6321] = { id = 6321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplying Brill", description = "Executor Zygand asked me to take stock of our equipment here in Brill.  With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need.\n\nI found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field.\n\nHere is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity.  Take the order to Bat Handler Anette and speak with her about transport to the Undercity.", sourceObjective = "Bring Morris's Order to Bat Handler Anette.", progress = "You appear to be on official business...", completion = "Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for the Sepulcher must not be left under stocked.", sourceObjectiveStatus = "unverified-source-field" }
quests[6322] = { id = 6322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Michael Garrett", description = "I have placed Brill's supplies into this crate.  If you have already visited Brill and spoken with their bat master, then you may ride a bat back to her.\n\nSpeak with the Undercity's bat master, Michael Garrett.  He can provide you with a bat to Brill.", sourceObjective = "Bring Gordon's Crate to Michael Garrett.", progress = "If you must travel a long distance, then a bat is your best option.", completion = "This crate must reach the Sepulcher in Silverpine?  That is easily done; our bats fly there daily.", sourceObjectiveStatus = "unverified-source-field" }
quests[6323] = { id = 6323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to the Undercity", description = "One of my bats can take you to the Undercity.  Normally these flights require a small fee, but the flight to Undercity is complimentary for a <handsome/lovely> {race} like you.  Speak with me again when you are ready so that we may arrange your transport.\n\nYou will find Gordon Wendham in the Trade Quarter of the Undercity.  That is the same quarter where my bat will land.", sourceObjective = "Request a bat ride to the Undercity from the bat master Bat Handler Anette, then take Morris's Order to Gordon Wendham in the Undercity.", progress = "I keep my weapons in top condition.  They are cleaned and ready for use.", completion = "An order from the Sepulcher?  Very well.  It is an honor to serve those who serve our Dark Lady.", sourceObjectiveStatus = "unverified-source-field" }
quests[6324] = { id = 6324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Morris", description = "The bat master in Brill is Bat Handler Anette.  If you have already met her, then I can give you a bat to fly back to her.\n\nOur bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master.\n\nYou have met Anette in Brill, so you may now fly bats there.  Speak with me again when you are ready.", sourceObjective = "Buy a bat ride to Brill from the bat master Michael Garrett, then bring Gordon's Crate to Deathguard Morris in Brill.", progress = "{name}, you return.  Do you have our supplies from the Undercity?", completion = "Good work, {name}.  These weapons will ensure our Deathguards don't get caught unprepared.\n\nYou have done a valuable service for our Dark Lady.", sourceObjectiveStatus = "unverified-source-field" }
quests[6341] = { id = 6341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Darnassus", description = "Everyone in Dolanaar is so proud of Sister Aquinne. I'm certain she'll be pleased to receive this thoughtful gift from Nyoma.\n\nWhen you're ready to travel to Darnassus, just speak to me again and for a few coins, you can hire a hippogryph to take you there. I'm told Sister Aquinne enjoys the solitude of a small plaza just south of the hippogryph master in Darnassus. Look for her there after you arrive.", sourceObjective = "Speak to Fidelio to purchase a flight to Darnassus, then bring the Dolanaar Recipe Book to Sister Aquinne in Darnassus.", progress = "How may I help you?  Are you in need of transport?", completion = "Ah, you wish to get this to Auberdine?  Very well...", sourceObjectiveStatus = "unverified-source-field" }
quests[6342] = { id = 6342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Unexpected Gift", description = "This is wonderful! It's just the kind of thing I need to remind me of home while I continue my studies in the Temple of the Moon. I'll try out one of the recipes tonight. I can't wait!\n\nWould you take this short note of thanks back to Nyoma? You can hire a hippogryph to take you back to Dolanaar. Just visit our hippogryph master, Leora, when you're ready to leave. She'll help you get a ride back to Dolanaar.", sourceObjective = "Bring Sister Aquinne's Note to Leora, the hippogryph master in Darnassus.", progress = "Have you come from Teldrassil?  Tell me, how is the fishing there?", completion = "A package from Nessa?  Thank you, {name}!  She told me she would send me samples of the fish caught near Rut'theran village.  She thinks they may be very different from the fish caught here...\n\nMy!  This jawbone is nearly twice the size of the same fish found here.  And these scales are as big as a closed fist!  Amazing!", sourceObjectiveStatus = "unverified-source-field" }
quests[6343] = { id = 6343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Nyoma", description = "It will be easy to get you a flight back to Dolanaar. Since you already know Fidelio in Dolanaar, you'll be able to fly back there without any problems.\n\nWhenever you arrive in a new town, you should remember to speak to the flight master so that you can fly to and from the new location.\n\nSpeak with me when you're ready to hire a hippogryph to return to Dolanaar.", sourceObjective = "Speak to Leora to hire a hippogryph to take you back to Dolanaar. Once you've arrived in Dolanaar, take Sister Aquinne's Note to Nyoma.", progress = "{name}, you're back from Auberdine?  Did you speak with Laird?", completion = "This is very interesting.  The fish here are large, but I didn't think the difference in bounties between here and the mainland was so great.  There must be a reason for this...\n\nWell thank you, {name}.  I will discuss with the villagers the news you brought.  Perhaps, one day, we will find the root of this oddity.  But until then, we shall reap its benefits!", sourceObjectiveStatus = "unverified-source-field" }
quests[6344] = { id = 6344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reminders of Home", description = "A friend of mine, Sister Aquinne, is training to be a priestess of the moon in Darnassus.  She left Dolanaar to study in the temple last year. Her letters say she is doing well and learning much, but she misses home and her old friends. I've put together a book of her favorite recipes from Dolanaar.\n\nIf you have time, would you take them to her in Darnassus? You can rent a hippogryph from Fidelio. He's in the center of town, just across from the inn.", sourceObjective = "Bring the Dolanaar Recipe Book to Fidelio in Dolanaar.", progress = "How can I help you?", completion = "Yes, I have need of a courier who will take a package to Darkshore.  Will you help me?", sourceObjectiveStatus = "unverified-source-field" }
quests[6361] = { id = 6361, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bundle of Hides", description = "I have a bundle of hides from the animals of Mulgore, and must get them to Thunder Bluff.  A colleague there, Ahanu, will use the hides to create leather goods.\n\nWill you take the hides to him for me?\n\nThe quickest way to Thunder Bluff is on the back of a wind rider.  Bring the bundle of hides to Tak, our wind rider master in Bloodhoof Village, and speak to him about transport to Thunder Bluff.", sourceObjective = "Bring the Bundle of Hides to the wind rider master Tak in Bloodhoof Village.", progress = "Are you here for a wind rider?  You have something to transport?", completion = "If you must take these hides to Thunder Bluff, then you are speaking to the right orc!", sourceObjectiveStatus = "unverified-source-field" }
quests[6362] = { id = 6362, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to Thunder Bluff", description = "For a small fee, I will give you a wind rider to Thunder Bluff.  There's no faster way to the city!\n\nIf that is acceptable, speak to me again when you are ready to go.\n\nIf you're taking those hides to Ahanu, then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff.  And that's right where you'll land!", sourceObjective = "Buy a wind rider to Thunder Bluff from the wind rider master Tak, then bring the Bundle of Hides to Ahanu in Thunder Bluff.", progress = "There is dust on your shoulders that must be from the Barrens.  You have spoken with my friend Jahan?", completion = "Ah, a new bundle of hides.  I will get to work on these immediately!\n\nThank you, brother.  You have done me a great service.  Here are some coins to pay for your time and travel costs.", sourceObjectiveStatus = "unverified-source-field" }
quests[6363] = { id = 6363, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal the Wind Rider Master", description = "I have prepared leather goods for Varg to sell at the Bloodhoof Village.  Will you bring them to him?\n\nIf you have already been to Bloodhoof Village and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him.\n\nTake the leather goods to Tal, our wind rider master in Thunder Bluff, and speak with him to arrange transport to Bloodhoof Village.", sourceObjective = "Bring Ahanu's Leather Goods to Tal in Thunder Bluff.", progress = "Greetings, {class}.  What can I do for you?", completion = "You need to take this to the Crossroads, eh?  That's not a problem.  If you've already been there and spoken to Devrak, then you can take one of my wind riders back to him.", sourceObjectiveStatus = "unverified-source-field" }
quests[6364] = { id = 6364, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Varg", description = "In order to fly to a town, you must have already been there and spoken with the wind rider master of that town.  You have been to the Bloodhoof Village and spoken to their wind rider master Tak, so for a small fee you can take a wind rider to him from here.\n\nSpeak with me again when you are ready.  Once at Bloodhoof Village, you can then deliver the leather goods to Varg Whisperwind.", sourceObjective = "Buy a wind rider to Bloodhoof Village from the wind rider master Tal, then bring Ahanu's Leather Goods to Varg Whisperwind.", progress = "{name}, you are back from Thunder Bluff?  Did you deliver the hides to Ahanu?", completion = "Ahanu sent me finished products?  Very good.  There are many hunters and adventurers in the Crossroads now and business is lively.  I am sure I'll sell these goods very soon.\n\nThank you for all your efforts, {name}.  I am in your debt.", sourceObjectiveStatus = "unverified-source-field" }
quests[6365] = { id = 6365, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meats to Orgrimmar", description = "I have some choice cuts of meat that I want to send to a friend.  Her name is Gryshka, the innkeeper in Orgrimmar.  Will you deliver the meat for me?\n\nThe fastest way to Orgrimmar is on a wind rider.  Take the meats to the Razor Hill wind rider master, Burok, and speak with him about transport to Orgrimmar.", sourceObjective = "Bring Grimtak's Meats to Burok in Razor Hill.", progress = "You need to get somewhere fast?  Then you're talking to the right {race}!", completion = "You have to get this meat to Orgrimmar?  That is no problem.  For a small fee, my wind rider can take you there.", sourceObjectiveStatus = "unverified-source-field" }
quests[6381] = { id = 6381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Life", description = "As you have seen, {class}, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale. Beware, for harpies and angry fire elementals still plague the scarred land.\n\n{name}, take these enchanted Gaea seeds and plant them in fertile mounds of soil. The cycle of life must go on!", sourceObjective = "Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.", progress = "These seeds you plant are strong, resisting corruption, and making a foothold for other life. They will grow and grow, first preventing corruption and healing the scarred land, and then one day, restoring Stonetalon to a lush forest, once again.\n\nHave you planted all of the Gaea seeds?", completion = "This is great victory for the land. In time, other things will come to pass: the Venture Co. will pack up their buzz saws and axes, the angry fire spirits will calm, and the harpies will be pushed out by the land.\n\nOnly then {name}, will Stonetalon be truly at peace.\n\nYou have done well {class}; take one of these items as thanks for the new life you have created here today.", sourceObjectiveStatus = "unverified-source-field" }
quests[6382] = { id = 6382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashenvale Hunt", description = "Your strength impresses me, {class}.  Your willingness to embrace the hunt gives me confidence that you could move on to bigger game... and bigger challenges.\n\nThe forests of Ashenvale represent a vast untamed wild that the Horde seeks to impose its own will upon, both politically and spiritually.  If you seek to prove yourself in an unproven land, seek the guidance of Senani Thunderheart in Splintertree Post.  The outpost is due north of the path leading from the Barrens.", sourceObjective = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", completion = "Welcome to the new frontier, {name}.  Ashenvale is a land of opportunity, one where a young {class} like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.", sourceObjectiveStatus = "unverified-source-field" }
quests[6383] = { id = 6383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ashenvale Hunt", sourceObjective = "There are three legendary creatures that make up the Ashenvale Hunt; you may seek them and test yourself against their cunning and might.  In the process, you will hopefully learn something about yourself.  The creatures are: the bear Ursangous, the nightsaber cat Shadumbra, and the hippogryph Sharptalon.\n\nThe creatures of the Ashenvale Hunt are powerful, and you may find that you'll need aid in bringing them down.  If you should best them, bring me proof of your deed.", sourceObjectiveStatus = "unverified-source-field" }
quests[6384] = { id = 6384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ride to Orgrimmar", description = "For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Grimtak's meats to Gryshka.  Her inn is in the Valley of Strength.\n\nSpeak with me again when you are ready for the journey.", sourceObjective = "Buy a wind rider to Orgrimmar from the wind rider master Burok, then bring Grimtak's Meats to Gryshka in Orgrimmar.", progress = "Something smells good!  You don't have raw meat on you, do you?", completion = "Oh, wonderful!  Those are fine cuts!  These are from Zargh, are they?  That {race} sure knows his way into a lady's heart...\n\nOh, I can't wait to cook it.  But not too much!  Meat is best served rare, don't you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[6385] = { id = 6385, flavor = "source-reference", locale = "enUS", source = "MultiLanguage cata cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceFlavor = "cata", sourceRevision = "cc638509ca3347e4c22bf6187dac4c2443b9057d", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doras the Wind Rider Master", description = "I've written a letter of thanks to Grimtak.  Will you deliver it for me?  If you've already been to the Razor Hill and spoken with their wind rider master, then you can fly a wind rider back there.\n\nTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to Razor Hill.", sourceObjective = "Bring Gryshka's Letter to Doras in Orgrimmar.", progress = "Do you need one of my wind riders?", completion = "You have to get this to the Crossroads in the Barrens?  Yes, I can get you there...", sourceObjectiveStatus = "unverified-source-field" }
